$script:AtlasXamlTemplate = '<Window
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
    Title="{{WINDOW_TITLE}}"
    Height="{{WINDOW_HEIGHT}}"
    Width="{{WINDOW_WIDTH}}"
    MinWidth="{{WINDOW_MIN_WIDTH}}"
    MinHeight="{{WINDOW_MIN_HEIGHT}}"
    WindowStartupLocation="CenterScreen"
    Background="{{BG_COLOR}}"
    FontFamily="{{FONT_FAMILY}}"
    FontSize="13"
    TextOptions.TextFormattingMode="Display"
    TextOptions.TextRenderingMode="ClearType">

    <Window.Resources>
        <!-- Paleta Atlas -->
        <SolidColorBrush x:Key="AccentBrush"         Color="{{ACCENT_COLOR}}"/>
        <SolidColorBrush x:Key="AccentHoverBrush"    Color="{{ACCENT_HOVER}}"/>
        <SolidColorBrush x:Key="AccentPressedBrush"  Color="{{ACCENT_PRESSED}}"/>
        <SolidColorBrush x:Key="SurfaceBrush"        Color="{{SURFACE_COLOR}}"/>
        <SolidColorBrush x:Key="SurfaceAltBrush"     Color="{{SURFACE_ALT_COLOR}}"/>
        <SolidColorBrush x:Key="BorderBrush"         Color="{{BORDER_COLOR}}"/>
        <SolidColorBrush x:Key="TextPrimaryBrush"    Color="{{TEXT_PRIMARY}}"/>
        <SolidColorBrush x:Key="TextSecondaryBrush"  Color="{{TEXT_SECONDARY}}"/>
        <SolidColorBrush x:Key="TextMutedBrush"      Color="{{TEXT_MUTED}}"/>

        <!-- Botón primario (estilo Fluent) -->
        <Style x:Key="AtlasPrimaryButton" TargetType="Button">
            <Setter Property="Background" Value="{StaticResource AccentBrush}"/>
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="BorderBrush" Value="{StaticResource AccentBrush}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Padding" Value="16,8"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border CornerRadius="{{CORNER_RADIUS}}"
                                Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}">
                            <ContentPresenter HorizontalAlignment="Center"
                                              VerticalAlignment="Center"
                                              Margin="{TemplateBinding Padding}"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter Property="Background" Value="{StaticResource AccentHoverBrush}"/>
                                <Setter Property="BorderBrush" Value="{StaticResource AccentHoverBrush}"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter Property="Background" Value="{StaticResource AccentPressedBrush}"/>
                            </Trigger>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter Property="BorderBrush" Value="{StaticResource TextPrimaryBrush}"/>
                                <Setter Property="BorderThickness" Value="2"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Botón secundario (outline) -->
        <Style x:Key="AtlasSecondaryButton" TargetType="Button" BasedOn="{StaticResource AtlasPrimaryButton}">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Foreground" Value="{StaticResource TextPrimaryBrush}"/>
            <Setter Property="BorderBrush" Value="{StaticResource BorderBrush}"/>
        </Style>

        <!-- Tarjeta de herramienta -->
        <Style x:Key="ToolCard" TargetType="Border">
            <Setter Property="Background" Value="{StaticResource SurfaceBrush}"/>
            <Setter Property="BorderBrush" Value="{StaticResource BorderBrush}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="CornerRadius" Value="{{CORNER_RADIUS}}"/>
            <Setter Property="Padding" Value="16"/>
            <Setter Property="Margin" Value="0,0,12,12"/>
        </Style>

        <!-- Categoría pill -->
        <Style x:Key="CategoryPill" TargetType="RadioButton">
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Foreground" Value="{StaticResource TextSecondaryBrush}"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Padding" Value="14,8"/>
            <Setter Property="Margin" Value="0,0,8,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="RadioButton">
                        <Border x:Name="Pill"
                                CornerRadius="{{CORNER_RADIUS}}"
                                Background="Transparent"
                                BorderBrush="Transparent"
                                BorderThickness="{TemplateBinding BorderThickness}">
                            <ContentPresenter HorizontalAlignment="Center"
                                              VerticalAlignment="Center"
                                              Margin="{TemplateBinding Padding}"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Pill" Property="Background" Value="{StaticResource SurfaceAltBrush}"/>
                            </Trigger>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="Pill" Property="Background" Value="{StaticResource AccentBrush}"/>
                                <Setter Property="Foreground" Value="White"/>
                            </Trigger>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="Pill" Property="BorderBrush" Value="{StaticResource TextPrimaryBrush}"/>
                                <Setter Property="BorderThickness" Value="2"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Scrollbar minimalista -->
        <Style TargetType="ScrollBar">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Width" Value="10"/>
        </Style>

        <!-- ComboBox Atlas (header) - ControlTemplate completo para que el combo se integre
             visualmente con la barra superior. Usa las brushes del tema (SurfaceBrush,
             BorderBrush, TextPrimaryBrush) para que empalme con el header como una sola pieza.
             Sin ControlTemplate, WPF pinta el combo con chrome Aero blanco aunque se fije
             Background/Foreground. -->
        <Style x:Key="AtlasComboBox" TargetType="ComboBox">
            <Setter Property="Foreground" Value="{StaticResource TextPrimaryBrush}"/>
            <Setter Property="Background" Value="{StaticResource SurfaceBrush}"/>
            <Setter Property="BorderBrush" Value="{StaticResource BorderBrush}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Padding" Value="10,6"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="SnapsToDevicePixels" Value="True"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ComboBox">
                        <Grid>
                            <ToggleButton x:Name="ToggleButton"
                                          Focusable="False"
                                          ClickMode="Press"
                                          IsChecked="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}">
                                <ToggleButton.Template>
                                    <ControlTemplate TargetType="ToggleButton">
                                        <Border x:Name="TBBorder"
                                                CornerRadius="{{CORNER_RADIUS}}"
                                                Background="{StaticResource SurfaceBrush}"
                                                BorderBrush="{StaticResource BorderBrush}"
                                                BorderThickness="1">
                                            <Grid>
                                                <Grid.ColumnDefinitions>
                                                    <ColumnDefinition Width="*"/>
                                                    <ColumnDefinition Width="22"/>
                                                </Grid.ColumnDefinitions>
                                                <Path Grid.Column="1"
                                                      Data="M 0 0 L 4 4 L 8 0 Z"
                                                      Fill="{StaticResource TextSecondaryBrush}"
                                                      HorizontalAlignment="Center"
                                                      VerticalAlignment="Center"/>
                                            </Grid>
                                        </Border>
                                        <ControlTemplate.Triggers>
                                            <Trigger Property="IsMouseOver" Value="True">
                                                <Setter TargetName="TBBorder" Property="Background" Value="{StaticResource SurfaceAltBrush}"/>
                                            </Trigger>
                                            <Trigger Property="IsChecked" Value="True">
                                                <Setter TargetName="TBBorder" Property="Background" Value="{StaticResource SurfaceAltBrush}"/>
                                            </Trigger>
                                        </ControlTemplate.Triggers>
                                    </ControlTemplate>
                                </ToggleButton.Template>
                            </ToggleButton>
                            <ContentPresenter x:Name="ContentSite"
                                              IsHitTestVisible="False"
                                              Content="{TemplateBinding SelectionBoxItem}"
                                              ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}"
                                              ContentTemplateSelector="{TemplateBinding ItemTemplateSelector}"
                                              Margin="{TemplateBinding Padding}"
                                              VerticalAlignment="Center"
                                              HorizontalAlignment="Left"
                                              TextElement.Foreground="{StaticResource TextPrimaryBrush}"/>
                            <Popup x:Name="Popup"
                                   Placement="Bottom"
                                   IsOpen="{TemplateBinding IsDropDownOpen}"
                                   AllowsTransparency="True"
                                   Focusable="False"
                                   PopupAnimation="Slide">
                                <Border Background="{StaticResource SurfaceBrush}"
                                        BorderBrush="{StaticResource BorderBrush}"
                                        BorderThickness="1"
                                        CornerRadius="{{CORNER_RADIUS}}"
                                        MinWidth="{TemplateBinding ActualWidth}"
                                        SnapsToDevicePixels="True">
                                    <ScrollViewer SnapsToDevicePixels="True">
                                        <StackPanel IsItemsHost="True"
                                                    KeyboardNavigation.DirectionalNavigation="Contained"/>
                                    </ScrollViewer>
                                </Border>
                            </Popup>
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
            <Style.Resources>
                <Style TargetType="ComboBoxItem">
                    <Setter Property="Background" Value="Transparent"/>
                    <Setter Property="Foreground" Value="{StaticResource TextPrimaryBrush}"/>
                    <Setter Property="Padding" Value="10,6"/>
                    <Setter Property="Cursor" Value="Hand"/>
                    <Setter Property="Template">
                        <Setter.Value>
                            <ControlTemplate TargetType="ComboBoxItem">
                                <Border x:Name="ItemBorder"
                                        Background="{TemplateBinding Background}"
                                        Padding="{TemplateBinding Padding}">
                                    <ContentPresenter TextElement.Foreground="{TemplateBinding Foreground}"/>
                                </Border>
                                <ControlTemplate.Triggers>
                                    <Trigger Property="IsHighlighted" Value="True">
                                        <Setter TargetName="ItemBorder" Property="Background" Value="{StaticResource SurfaceAltBrush}"/>
                                    </Trigger>
                                    <Trigger Property="IsSelected" Value="True">
                                        <Setter TargetName="ItemBorder" Property="Background" Value="{StaticResource SurfaceAltBrush}"/>
                                    </Trigger>
                                </ControlTemplate.Triggers>
                            </ControlTemplate>
                        </Setter.Value>
                    </Setter>
                </Style>
            </Style.Resources>
        </Style>
    </Window.Resources>

    <Grid>
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>   <!-- Header -->
            <RowDefinition Height="Auto"/>   <!-- Dashboard banner -->
            <RowDefinition Height="Auto"/>   <!-- Tabs -->
            <RowDefinition Height="*"/>      <!-- Sidebar + Content -->
            <RowDefinition Height="Auto"/>   <!-- Footer -->
        </Grid.RowDefinitions>

        <!-- HEADER -->
        <Border Grid.Row="0" Background="{StaticResource SurfaceBrush}"
                BorderBrush="{StaticResource BorderBrush}"
                BorderThickness="0,0,0,1"
                Padding="24,18">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>

                <StackPanel Grid.Column="0" Orientation="Vertical">
                    <TextBlock Text="{{BRAND_NAME}}"
                               Foreground="{StaticResource AccentBrush}"
                               FontSize="22"
                               FontWeight="Bold"/>
                    <TextBlock Text="{{BRAND_TAGLINE}}"
                               Foreground="{StaticResource TextMutedBrush}"
                               FontSize="12"
                               Margin="0,2,0,0"/>
                </StackPanel>

                <TextBox x:Name="SearchBox"
                         AutomationProperties.Name="{{SEARCH_PLACEHOLDER}}"
                         Grid.Column="1"
                         MaxWidth="360"
                         Margin="24,0"
                         Padding="12,8"
                         Background="{StaticResource SurfaceAltBrush}"
                         Foreground="{StaticResource TextPrimaryBrush}"
                         BorderBrush="{StaticResource BorderBrush}"
                         FontSize="13"
                         VerticalContentAlignment="Center"
                         Tag="🔍  {{SEARCH_PLACEHOLDER}}"/>

                <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center">
                    <TextBlock x:Name="AdminBadge"
                               Text=""
                               Foreground="{StaticResource TextMutedBrush}"
                               FontSize="11"
                               Margin="0,0,12,0"
                               VerticalAlignment="Center"/>
                    <ComboBox x:Name="LanguageCombo"
                              AutomationProperties.Name="{{LANG_TOOLTIP}}"
                              Style="{StaticResource AtlasComboBox}"
                              Width="130"
                              Height="34"
                              Margin="0,0,6,0"
                              FontSize="12"
                              VerticalContentAlignment="Center"
                              ToolTip="{{LANG_TOOLTIP}}"/>
                    <Button x:Name="BtnRestart"
                            AutomationProperties.Name="{{RESTART_TOOLTIP}}"
                            Content="↻"
                            Style="{StaticResource AtlasSecondaryButton}"
                            Margin="0,0,8,0"
                            Padding="10,6"
                            FontSize="16"
                            ToolTip="{{RESTART_TOOLTIP}}"/>
                    <Button x:Name="BtnLogs"
                            Content="{{HEADER_LOGS}}"
                            Style="{StaticResource AtlasSecondaryButton}"
                            Margin="0,0,8,0"/>
                    <Button x:Name="BtnAbout"
                            Content="{{HEADER_ABOUT}}"
                            Style="{StaticResource AtlasSecondaryButton}"/>
                </StackPanel>
            </Grid>
        </Border>

        <!-- DASHBOARD BANNER (live system metrics) -->
        <Border Grid.Row="1"
                Background="{StaticResource SurfaceBrush}"
                BorderBrush="{StaticResource BorderBrush}"
                BorderThickness="0,0,0,1"
                Padding="24,10">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="2*"/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>

                <!-- CPU -->
                <StackPanel Grid.Column="0" Margin="0,0,16,0">
                    <Grid Margin="0,0,0,4">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Grid.Column="0"
                                   Text="{{DASH_CPU}}"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="11"
                                   FontWeight="SemiBold"/>
                        <TextBlock Grid.Column="1"
                                   x:Name="DashCpuValue"
                                   Text="--%"
                                   Foreground="{StaticResource TextPrimaryBrush}"
                                   FontSize="12"
                                   FontWeight="SemiBold"/>
                    </Grid>
                    <ProgressBar x:Name="DashCpuBar"
                                 Height="6"
                                 Minimum="0"
                                 Maximum="100"
                                 Value="0"
                                 Background="{StaticResource SurfaceAltBrush}"
                                 Foreground="{StaticResource AccentBrush}"
                                 BorderThickness="0"/>
                </StackPanel>

                <!-- RAM -->
                <StackPanel Grid.Column="1" Margin="0,0,16,0">
                    <Grid Margin="0,0,0,4">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Grid.Column="0"
                                   Text="{{DASH_RAM}}"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="11"
                                   FontWeight="SemiBold"/>
                        <TextBlock Grid.Column="1"
                                   x:Name="DashRamValue"
                                   Text="--%"
                                   Foreground="{StaticResource TextPrimaryBrush}"
                                   FontSize="12"
                                   FontWeight="SemiBold"/>
                    </Grid>
                    <ProgressBar x:Name="DashRamBar"
                                 Height="6"
                                 Minimum="0"
                                 Maximum="100"
                                 Value="0"
                                 Background="{StaticResource SurfaceAltBrush}"
                                 Foreground="{StaticResource AccentBrush}"
                                 BorderThickness="0"/>
                </StackPanel>

                <!-- DISK (system drive) -->
                <StackPanel Grid.Column="2" Margin="0,0,16,0">
                    <Grid Margin="0,0,0,4">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Grid.Column="0"
                                   Text="{{DASH_DISK}}"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="11"
                                   FontWeight="SemiBold"/>
                        <TextBlock Grid.Column="1"
                                   x:Name="DashDiskValue"
                                   Text="--%"
                                   Foreground="{StaticResource TextPrimaryBrush}"
                                   FontSize="12"
                                   FontWeight="SemiBold"/>
                    </Grid>
                    <ProgressBar x:Name="DashDiskBar"
                                 Height="6"
                                 Minimum="0"
                                 Maximum="100"
                                 Value="0"
                                 Background="{StaticResource SurfaceAltBrush}"
                                 Foreground="{StaticResource AccentBrush}"
                                 BorderThickness="0"/>
                </StackPanel>

                <!-- ALERTS -->
                <StackPanel Grid.Column="3" VerticalAlignment="Center">
                    <TextBlock Text="{{DASH_ALERTS}}"
                               Foreground="{StaticResource TextMutedBrush}"
                               FontSize="11"
                               FontWeight="SemiBold"
                               Margin="0,0,0,4"/>
                    <TextBlock x:Name="DashAlertsText"
                               Text="--"
                               Foreground="{StaticResource TextSecondaryBrush}"
                               FontSize="12"
                               TextWrapping="Wrap"/>
                </StackPanel>

                <!-- RESOURCE MONITOR CONTROLS -->
                <StackPanel Grid.Column="4"
                            Orientation="Horizontal"
                            VerticalAlignment="Center"
                            Margin="12,0,0,0">
                    <Button x:Name="BtnDashMonitorToggle"
                            Content="{{DASH_TOGGLE_OFF}}"
                            Style="{StaticResource AtlasSecondaryButton}"
                            Padding="10,6"
                            FontSize="12"
                            ToolTip="{{DASH_TOGGLE_TOOLTIP}}"/>
                    <Button x:Name="BtnDashRefresh"
                            AutomationProperties.Name="{{DASH_REFRESH_TOOLTIP}}"
                            Content="↻"
                            Style="{StaticResource AtlasSecondaryButton}"
                            Margin="8,0,0,0"
                            Padding="10,6"
                            FontSize="16"
                            ToolTip="{{DASH_REFRESH_TOOLTIP}}"/>
                </StackPanel>
            </Grid>
        </Border>

        <!-- TABS / CATEGORÍAS -->
        <Border Grid.Row="2"
                Background="{{BG_COLOR}}"
                Padding="24,12,24,0">
            <ScrollViewer HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Disabled">
            <StackPanel x:Name="CategoryBar"
                        Orientation="Horizontal"
                        VerticalAlignment="Center"/>
            </ScrollViewer>
        </Border>

        <!-- SIDEBAR + CONTENT -->
        <Grid Grid.Row="3">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="240"/>
                <ColumnDefinition Width="*"/>
            </Grid.ColumnDefinitions>

            <!-- SIDEBAR (always visible PC info) -->
            <Border Grid.Column="0"
                    Background="{StaticResource SurfaceBrush}"
                    BorderBrush="{StaticResource BorderBrush}"
                    BorderThickness="0,1,1,0"
                    Padding="16,16,16,16">
                <ScrollViewer VerticalScrollBarVisibility="Auto"
                              HorizontalScrollBarVisibility="Disabled">
                    <StackPanel>
                        <Grid Margin="0,0,0,12">
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="*"/>
                                <ColumnDefinition Width="Auto"/>
                            </Grid.ColumnDefinitions>
                            <TextBlock Grid.Column="0"
                                       Text="{{SIDEBAR_HEADER}}"
                                       Foreground="{StaticResource TextMutedBrush}"
                                       FontSize="11"
                                       FontWeight="SemiBold"
                                       VerticalAlignment="Center"/>
                            <Button x:Name="BtnLoadSysInfo"
                                    Content="{{SIDEBAR_LOAD_BTN}}"
                                    Grid.Column="1"
                                    Style="{StaticResource AtlasSecondaryButton}"
                                    Padding="8,4"
                                    FontSize="11"
                                    VerticalAlignment="Center"/>
                        </Grid>

                        <!-- Hostname -->
                        <TextBlock Text="{{SIDEBAR_HOST}}"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="10"
                                   Margin="0,0,0,2"/>
                        <TextBlock x:Name="SideHost"
                                   Text="--"
                                   Foreground="{StaticResource TextPrimaryBrush}"
                                   FontSize="13"
                                   FontWeight="SemiBold"
                                   TextTrimming="CharacterEllipsis"
                                   Margin="0,0,0,10"/>

                        <!-- User -->
                        <TextBlock Text="{{SIDEBAR_USER}}"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="10"
                                   Margin="0,0,0,2"/>
                        <TextBlock x:Name="SideUser"
                                   Text="--"
                                   Foreground="{StaticResource TextPrimaryBrush}"
                                   FontSize="12"
                                   TextTrimming="CharacterEllipsis"
                                   Margin="0,0,0,10"/>

                        <!-- OS -->
                        <TextBlock Text="{{SIDEBAR_OS}}"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="10"
                                   Margin="0,0,0,2"/>
                        <TextBlock x:Name="SideOS"
                                   Text="--"
                                   Foreground="{StaticResource TextPrimaryBrush}"
                                   FontSize="12"
                                   TextWrapping="Wrap"
                                   Margin="0,0,0,10"/>

                        <!-- CPU model -->
                        <TextBlock Text="{{SIDEBAR_CPU}}"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="10"
                                   Margin="0,0,0,2"/>
                        <TextBlock x:Name="SideCpu"
                                   Text="--"
                                   Foreground="{StaticResource TextPrimaryBrush}"
                                   FontSize="11"
                                   TextWrapping="Wrap"
                                   Margin="0,0,0,10"/>

                        <!-- RAM total -->
                        <TextBlock Text="{{SIDEBAR_RAM}}"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="10"
                                   Margin="0,0,0,2"/>
                        <TextBlock x:Name="SideRam"
                                   Text="--"
                                   Foreground="{StaticResource TextPrimaryBrush}"
                                   FontSize="12"
                                   Margin="0,0,0,10"/>

                        <!-- Uptime -->
                        <TextBlock Text="{{SIDEBAR_UPTIME}}"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="10"
                                   Margin="0,0,0,2"/>
                        <TextBlock x:Name="SideUptime"
                                   Text="--"
                                   Foreground="{StaticResource TextPrimaryBrush}"
                                   FontSize="12"
                                   Margin="0,0,0,10"/>

                        <!-- IP -->
                        <TextBlock Text="{{SIDEBAR_IP}}"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="10"
                                   Margin="0,0,0,2"/>
                        <TextBlock x:Name="SideIp"
                                   Text="--"
                                   Foreground="{StaticResource TextPrimaryBrush}"
                                   FontSize="12"
                                   TextTrimming="CharacterEllipsis"
                                   Margin="0,0,0,10"/>

                        <!-- Last sync (when dashboard was last refreshed) -->
                        <TextBlock Text="{{SIDEBAR_LASTSYNC}}"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="10"
                                   Margin="0,0,0,2"/>
                        <TextBlock x:Name="SideLastSync"
                                   Text="--"
                                   Foreground="{StaticResource TextMutedBrush}"
                                   FontSize="11"
                                   FontStyle="Italic"
                                   Margin="0,0,0,4"/>
                    </StackPanel>
                </ScrollViewer>
            </Border>

            <!-- CONTENT -->
            <ScrollViewer Grid.Column="1"
                          VerticalScrollBarVisibility="Auto"
                          HorizontalScrollBarVisibility="Disabled"
                          Padding="24,12,24,12">
                <ItemsControl x:Name="ToolsGrid">
                    <ItemsControl.ItemsPanel>
                        <ItemsPanelTemplate>
                            <WrapPanel Orientation="Horizontal"/>
                        </ItemsPanelTemplate>
                    </ItemsControl.ItemsPanel>
                </ItemsControl>
            </ScrollViewer>
        </Grid>

        <!-- FOOTER -->
        <Border Grid.Row="4"
                Background="{StaticResource SurfaceBrush}"
                BorderBrush="{StaticResource BorderBrush}"
                BorderThickness="0,1,0,0"
                Padding="24,10">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <TextBlock Grid.Column="0"
                           x:Name="StatusText"
                           Text="{{STATUS_READY}}"
                           Foreground="{StaticResource TextMutedBrush}"
                           FontSize="11"
                           VerticalAlignment="Center"/>
                <Button Grid.Column="1"
                           x:Name="CoffeeLink"
                           Content="☕ {{COFFEE_LABEL}}"
                           Style="{StaticResource AtlasSecondaryButton}"
                           Background="Transparent" BorderBrush="Transparent" BorderThickness="0" Padding="0"
                           Foreground="{StaticResource AccentBrush}"
                           FontSize="11"
                           FontWeight="SemiBold"
                           Cursor="Hand"
                           VerticalAlignment="Center"
                           Margin="0,0,16,0"
                           ToolTip="{{COFFEE_TOOLTIP}}"/>
                <TextBlock Grid.Column="2"
                           Text="{{BRAND_COPYRIGHT}} · v{{BRAND_VERSION}}"
                           Foreground="{StaticResource TextMutedBrush}"
                           FontSize="11"
                           VerticalAlignment="Center"/>
            </Grid>
        </Border>
    </Grid>
</Window>
'
