function Get-AtlasReportDir {
    [CmdletBinding()]
    [OutputType([string])]
    param([string]$SubFolder)
    $base = Join-Path $env:USERPROFILE 'Documents\AtlasPC\reports'
    $dir  = if ($SubFolder) { Join-Path $base $SubFolder } else { $base }
    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    return $dir
}

function Get-AtlasReportPath {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)] [string]$Prefix,
        [string]$Extension = 'html',
        [string]$SubFolder
    )
    $dir   = Get-AtlasReportDir -SubFolder $SubFolder
    $stamp = Get-Date -Format 'yyyy-MM-dd_HHmmss'
    $ext   = $Extension.TrimStart('.')
    return (Join-Path $dir ("{0}_{1}.{2}" -f $Prefix, $stamp, $ext))
}

function ConvertTo-AtlasHtmlEncoded {
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory, ValueFromPipeline)][AllowEmptyString()][string]$Text)
    process {
        if ($null -eq $Text) { return '' }
        return [System.Net.WebUtility]::HtmlEncode($Text)
    }
}

function ConvertTo-AtlasHtmlDocument {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)] [string]$Title,
        [Parameter(Mandatory)] [string]$BodyHtml,
        [string]$AccentColor = '#0078D4',
        [string]$Subtitle
    )
    $safeTitle    = ConvertTo-AtlasHtmlEncoded $Title
    $safeSubtitle = if ($Subtitle) { ConvertTo-AtlasHtmlEncoded $Subtitle } else { '' }
    $generated    = (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')
    $subtitleHtml = if ($safeSubtitle) { "<p class='subtitle'>$safeSubtitle</p>" } else { '' }
    return @"
<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>$safeTitle</title>
<style>
  :root { --accent: $AccentColor; }
  * { box-sizing: border-box; }
  body { font-family: 'Segoe UI', system-ui, sans-serif; margin: 0; color: #1b1b1b; background: #f3f3f3; }
  header { background: var(--accent); color: #fff; padding: 24px 32px; }
  header h1 { margin: 0; font-size: 22px; }
  header .subtitle { margin: 6px 0 0; opacity: .9; font-size: 14px; }
  main { padding: 24px 32px; max-width: 1100px; margin: 0 auto; }
  section { background: #fff; border: 1px solid #e1e1e1; border-radius: 8px; padding: 16px 20px; margin-bottom: 16px; }
  h2 { font-size: 16px; border-bottom: 2px solid var(--accent); padding-bottom: 6px; }
  table { width: 100%; border-collapse: collapse; font-size: 14px; }
  th, td { text-align: left; padding: 8px 10px; border-bottom: 1px solid #eee; }
  th { background: #fafafa; }
  footer { text-align: center; color: #888; font-size: 12px; padding: 16px; }
  .ok { color: #107c10; } .warn { color: #c19c00; } .err { color: #d13438; }
</style>
</head>
<body>
<header>
  <h1>$safeTitle</h1>
  $subtitleHtml
</header>
<main>
$BodyHtml
</main>
<footer>Atlas PC Support &middot; generado $generated</footer>
</body>
</html>
"@
}

function Get-AtlasWingetPath {
    [CmdletBinding()]
    param()

    # 1) PATH normal
    $cmd = Get-Command winget.exe -ErrorAction SilentlyContinue
    if ($cmd -and $cmd.Source -and (Test-Path -LiteralPath $cmd.Source)) {
        return $cmd.Source
    }

    # 2) Ruta real del paquete Appx (evita el alias de WindowsApps de 0 bytes o faltante en admin elevacion)
    try {
        $pkg = Get-AppxPackage -Name 'Microsoft.DesktopAppInstaller' -ErrorAction SilentlyContinue |
               Sort-Object -Property Version -Descending |
               Select-Object -First 1

        if ($pkg -and $pkg.InstallLocation) {
            $exe = Join-Path $pkg.InstallLocation 'winget.exe'
            if (Test-Path -LiteralPath $exe) { return $exe }
        }
    } catch {}

    # 3) Elevado: buscar en Program Files\WindowsApps (si corre como admin diferente)
    try {
        $candidates = Get-ChildItem -LiteralPath 'C:\Program Files\WindowsApps' `
                                    -Filter 'Microsoft.DesktopAppInstaller_*' -Directory -ErrorAction SilentlyContinue |
                      Where-Object { $_.Name -match '^Microsoft\.DesktopAppInstaller_\d+\.\d+\.\d+\.\d+_x64__8wekyb3d8bbwe$' } |
                      Sort-Object { [version]($_.Name -split '_')[1] } -Descending
        foreach ($candidate in $candidates) {
            $exe = Join-Path $candidate.FullName 'winget.exe'
            if (Test-Path -LiteralPath $exe -PathType Leaf) { return $exe }
        }
    } catch {}

    return $null
}

function Get-AtlasWingetCapabilities {
    [CmdletBinding()]
    param([string]$WingetPath)

    $caps = [ordered]@{
        Available          = $false
        Version            = $null
        SupportsNoInteract = $false
        SupportsMsStore    = $false
        ProbeState         = 'Missing'
    }

    if (-not $WingetPath -or -not (Test-Path -LiteralPath $WingetPath)) { return $caps }

    $caps.ProbeState = 'NotEvaluated'
    try {
        $probe = Invoke-AtlasNativeProcess -FilePath $WingetPath -ArgumentList @('--version') -TimeoutSeconds 10
        $caps.ProbeState = $probe.State
        if ($probe.State -ne 'Correct') { return $caps }
        # Accept only WinGet's version response, never an error/banner or exit failure.
        $text = ([string]$probe.Stdout).Trim()
        $parsed = $null
        if ($text -notmatch '^v?(\d+\.\d+(?:\.\d+){0,2})(?:-[A-Za-z0-9.-]+)?$' -or
            -not [version]::TryParse($Matches[1], [ref]$parsed)) {
            $caps.ProbeState = 'NotEvaluated'
            return $caps
        }
        $caps.Available = $true
        $caps.Version = $text.TrimStart('v')
        $caps.SupportsNoInteract = ($parsed -ge [version]'1.4')
        $caps.SupportsMsStore = ($parsed -ge [version]'1.2')
    } catch {
        $caps.ProbeState = 'Failed'
    }

    return $caps
}


# ---- lib/Dependencies ----
# ============================================================
# Atlas PC Support - Dependency manager
# Resuelve y descarga dependencias externas (FastCopy, etc.)
# a %LOCALAPPDATA%\AtlasPC\bin\ bajo demanda.
# ============================================================

$script:AtlasDepsRegistry = @{}
foreach ($entry in $script:AtlasDependencyCatalog.PSObject.Properties) {
    $script:AtlasDepsRegistry[$entry.Name] = ConvertTo-AtlasHashtable $entry.Value
}

function Resolve-SymlinkPath {
    param([string]$Path)
    if (-not $Path) { return $Path }
    try {
        $item = Get-Item -LiteralPath $Path -ErrorAction Stop
        if ($item.Attributes -match "ReparsePoint") {
            if ($item.LinkTarget) { return $item.LinkTarget }
            elseif ($item.Target) {
                if ($item.Target -is [array]) { return $item.Target[0] }
                return [string]$item.Target
            }
        }
    } catch {}
    return $Path
}

function Test-AtlasDependencyHash {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$ExpectedSha256
    )

    if (-not (Test-Path -LiteralPath $Path)) { return $false }
    if (-not $ExpectedSha256) { return $false }

    $expected = $ExpectedSha256.ToLowerInvariant()
    if ($expected -notmatch '^[a-f0-9]{64}$') {
        Write-AtlasLog "Hash esperado invalido para dependencia: $ExpectedSha256" -Level WARN -Tool 'Deps'
        return $false
    }

    try {
        $actual = (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
        return ($actual -eq $expected)
    } catch {
        Write-AtlasLog "No se pudo calcular SHA256 para '$Path': $_" -Level WARN -Tool 'Deps'
        return $false
    }
}

function Resolve-AtlasDependency {
    <#
    .SYNOPSIS
    Busca una dependencia en el sistema; si no la encuentra,
    intenta instalarla con winget o descargarla.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][ValidatePattern('^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$')][string]$Name,
        [switch]$InstallIfMissing
    )

    if (-not $script:AtlasDepsRegistry.ContainsKey($Name)) {
        Write-AtlasLog "Dependencia desconocida: $Name" -Level ERROR -Tool 'Deps'
        return $null
    }
    $dep = $script:AtlasDepsRegistry[$Name]

    foreach ($p in $dep.SearchPaths) {
        $expanded = Expand-AtlasPath $p
        if (Test-Path $expanded) {
            # Ensure CrystalDiskInfo and CrystalDiskMark have their resource folders
            if ($Name -eq 'CrystalDiskInfo') {
                $parent = Split-Path -Parent $expanded
                if (-not (Test-Path -LiteralPath (Join-Path $parent 'CdiResource'))) {
                    Write-AtlasLog "Ignorando $Name en $expanded porque falta CdiResource" -Level WARN -Tool 'Deps'
                    continue
                }
            }
            if ($Name -eq 'CrystalDiskMark') {
                $parent = Split-Path -Parent $expanded
                if (-not (Test-Path -LiteralPath (Join-Path $parent 'CdmResource'))) {
                    Write-AtlasLog "Ignorando $Name en $expanded porque falta CdmResource" -Level WARN -Tool 'Deps'
                    continue
                }
            }
            Write-AtlasLog "Encontrada $Name en $expanded" -Tool 'Deps'
            return Resolve-SymlinkPath $expanded
        }
    }
    $inPath = Get-Command $dep.ExecutableName -ErrorAction SilentlyContinue
    if ($inPath) { return Resolve-SymlinkPath $inPath.Source }

    if (-not $InstallIfMissing) {
        Write-AtlasLog "$Name no encontrada (no se pidió instalar)." -Level WARN -Tool 'Deps'
        return $null
    }

    if ($dep.WingetId -and (Get-Command 'winget' -ErrorAction SilentlyContinue)) {
        Write-AtlasLog "Instalando $Name vía winget ($($dep.WingetId))" -Tool 'Deps'
        try {
            $result = Invoke-AtlasNativeProcess -FilePath 'winget.exe' -ArgumentList @('install','--id',$dep.WingetId,'--exact','--source','winget','--accept-source-agreements','--accept-package-agreements','--silent') -TimeoutSeconds 1800
            if ($result.State -ne 'Correct') { Write-AtlasLog "Dependency installation $($result.State), exit $($result.ExitCode); no second installer is started." -Level ERROR -Tool Deps; return $null }
        } catch {
            Write-AtlasLog "winget failed: $_; no second installer is started." -Level ERROR -Tool Deps
            return $null
        }
        return Resolve-AtlasDependency -Name $Name
    }

    # Fallback: direct download via DownloadUrl when winget is unavailable or failed
    if ($dep.DownloadUrl) {
        Write-AtlasLog "Intentando descarga directa de $Name ($($dep.DownloadUrl))" -Tool 'Deps'
        $cacheDir = Join-Path $env:LOCALAPPDATA 'AtlasPC\bin'
        if (-not (Test-Path $cacheDir)) { New-Item -ItemType Directory -Path $cacheDir -Force | Out-Null }
        $installerFile = Join-Path $cacheDir ("$Name-installer-" + [guid]::NewGuid().ToString('N').Substring(0,8) + '.exe')
        try {
            $ProgressPreference = 'SilentlyContinue'
            Invoke-WebRequest -Uri $dep.DownloadUrl -OutFile $installerFile -UseBasicParsing -TimeoutSec 120 -ErrorAction Stop
            if ((Get-Item $installerFile).Length -gt 100KB) {
                Assert-AtlasInstaller -Path $installerFile -ExpectedSha256 ([string]$dep.DownloadSha256)
                $targetDir = Join-Path $env:LOCALAPPDATA "AtlasPC\bin\$Name"
                if (-not (Test-Path $targetDir)) { New-Item -ItemType Directory -Path $targetDir -Force | Out-Null }
                if ($Name -ne 'FastCopy') { throw 'No direct extraction contract is defined for this dependency.' }
                $result = Invoke-AtlasNativeProcess -FilePath $installerFile -ArgumentList @('/EXTRACT64','/NOSUBDIR','/AGREE_LICENSE',("/DIR=$targetDir")) -TimeoutSeconds 180
                if ($result.State -ne 'Correct') { throw "Dependency extraction $($result.State), exit $($result.ExitCode). No alternative installer was started." }
                Remove-Item -LiteralPath $installerFile -ErrorAction Stop
                return Resolve-AtlasDependency -Name $Name
            }
        } catch {
            Write-AtlasLog "Descarga directa falló: $_" -Level WARN -Tool 'Deps'
            Remove-Item $installerFile -ErrorAction SilentlyContinue
        }
    }

    Write-AtlasLog "No se pudo resolver $Name. Revisa la ruta manualmente." -Level ERROR -Tool 'Deps'
    return $null
}

function Register-AtlasDependency {
    param(
        [Parameter(Mandatory)][ValidatePattern('^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$')][string]$Name,
        [Parameter(Mandatory)] [hashtable]$Definition
    )
    $script:AtlasDepsRegistry[$Name] = $Definition
}


# ---- lib/PS7 ----
# ============================================================
# Atlas PC Support - PowerShell 7 detection & install
#
# Proposito:
#   El panel soporta PS 5.1 (Windows de fabrica), pero las tools
#   sufren bugs de encoding, enums y parametros limitados de 5.1.
#   ToolRunner usa el runtime declarado por cada herramienta.
#   Detectar PS 7 no cambia silenciosamente ese contrato.
#
# Modo offline (USB):
#   Install-AtlasPS7 -OfflineSource "$PSScriptRoot\deps\PowerShell-*.msi"
#   Preparar USB copia el MSI en deps\ para instalacion sin internet.
# ============================================================

$ps7Definition = Get-AtlasDependencyDefinition -Name 'PowerShell7'
$script:AtlasPS7Version = $ps7Definition.Version
$script:AtlasPS7UrlX64 = $ps7Definition.DownloadUrl
$script:AtlasPS7MsiName = $ps7Definition.MsiName
$script:AtlasPS7HashesUrl = $ps7Definition.HashesUrl

function Get-AtlasPS7Path {
    <#
    .SYNOPSIS
      Devuelve la ruta completa a pwsh.exe si PS 7+ esta instalado, si no $null.
    #>
    [CmdletBinding()]
    param()

    # 1) PATH
    $cmd = Get-Command pwsh.exe -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($cmd -and $cmd.Path) { return $cmd.Path }

    # 2) Ruta por defecto de instalacion MSI (64-bit y 32-bit)
    $candidates = @(
        "$env:ProgramFiles\PowerShell\7\pwsh.exe",
        "${env:ProgramFiles(x86)}\PowerShell\7\pwsh.exe",
        "$env:LOCALAPPDATA\Microsoft\PowerShell\7\pwsh.exe"
    )
    foreach ($c in $candidates) {
        if (Test-Path -LiteralPath $c) { return (Resolve-Path -LiteralPath $c).Path }
    }

    return $null
}

function Find-AtlasPS7OfflineMsi {
    <#
    .SYNOPSIS
      Busca un MSI de PS 7 en carpetas locales conocidas (USB offline).
    #>
    [CmdletBinding()]
    param()

    $searchDirs = @()
    # USB offline root set by run-launcher.ps1 (highest priority — covers USB scenario)
    if ($env:ATLAS_OFFLINE_ROOT) {
        $searchDirs += (Join-Path $env:ATLAS_OFFLINE_ROOT 'deps')
    }
    # USB: si el launcher.ps1 esta en E:\ATLAS_PC_SUPPORT\, mirar deps\
    if ($script:AtlasRoot) {
        $searchDirs += (Join-Path $script:AtlasRoot 'deps')
    }
    # LOCALAPPDATA cache (Preparar USB guarda tambien alli)
    $searchDirs += (Join-Path $env:LOCALAPPDATA 'AtlasPC\deps')

    foreach ($dir in $searchDirs) {
        if (Test-Path -LiteralPath $dir) {
            $msi = Get-ChildItem -Path $dir -Filter $script:AtlasPS7MsiName -ErrorAction SilentlyContinue |
                Sort-Object Name -Descending | Select-Object -First 1
            if ($msi) { return $msi.FullName }
        }
    }
    return $null
}

function Get-AtlasPS7ExpectedHash {
    <#
    .SYNOPSIS
      Reads the independently pinned x64 MSI digest from the verified release.
    #>
    [CmdletBinding()]
    param()

    $hash = (Get-AtlasDependencyDefinition -Name PowerShell7).DownloadSha256
    if ($hash -cnotmatch '^[a-f0-9]{64}$') { throw 'Missing pinned PowerShell SHA-256.' }
    return $hash
}

function Test-AtlasFileHash {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$ExpectedHash
    )

    $actual = (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
    return ($actual -eq $ExpectedHash.ToLowerInvariant())
}

function Install-AtlasPS7 {
    <#
    .SYNOPSIS
      Instala PowerShell 7 usando msiexec silencioso.
      Intenta primero MSI local (offline), si no descarga de GitHub.

    .PARAMETER OfflineSource
      Ruta a un MSI ya descargado. Si se omite, se busca automaticamente
      y si no se encuentra se descarga.
    #>
    [CmdletBinding()]
    param(
        [string]$OfflineSource
    )

    $msi = $null
    $expectedHash = Get-AtlasPS7ExpectedHash
    $downloadedFromWeb = $false

    if ($OfflineSource -and (Test-Path -LiteralPath $OfflineSource)) {
        $msi = (Resolve-Path -LiteralPath $OfflineSource).Path
        Write-Host "  [>] Usando MSI local: $msi" -ForegroundColor Cyan
    } else {
        $found = Find-AtlasPS7OfflineMsi
        if ($found) {
            $msi = $found
            Write-Host "  [>] MSI local encontrado: $msi" -ForegroundColor Cyan
        }
    }

    if (-not $msi) {
        # Descargar
        $cacheDir = Join-Path $env:LOCALAPPDATA 'AtlasPC\deps'
        if (-not (Test-Path -LiteralPath $cacheDir)) {
            New-Item -ItemType Directory -Path $cacheDir -Force | Out-Null
        }
        $msi = Join-Path $cacheDir $script:AtlasPS7MsiName
        Write-Host "  [>] Descargando PowerShell $($script:AtlasPS7Version) (~120 MB)..." -ForegroundColor Cyan
        try {
            $expectedHash = Get-AtlasPS7ExpectedHash
            $ProgressPreference = 'SilentlyContinue'
            Invoke-WebRequest -Uri $script:AtlasPS7UrlX64 -OutFile $msi -UseBasicParsing
            $downloadedFromWeb = $true
        } catch {
            throw "Fallo descarga de PS 7: $($_.Exception.Message)"
        }
    }

    # The release pin is authoritative. A USB sidecar cannot replace it.
    if ($expectedHash) {
        Write-Host "  [>] Verificando integridad SHA-256 del MSI..." -ForegroundColor Cyan
        if (-not (Test-AtlasFileHash -Path $msi -ExpectedHash $expectedHash)) {
            if ($downloadedFromWeb) {
                Remove-Item -LiteralPath $msi -Force -ErrorAction SilentlyContinue
            }
            throw "La verificacion SHA-256 del MSI de PowerShell 7 fallo."
        }
        Write-Host "  [OK] Integridad verificada." -ForegroundColor Green
    } else {
        throw 'No se pudo validar SHA-256 del MSI. Se requiere su archivo .sha256 para instalar sin conexion.'
    }
    Assert-AtlasInstaller -Path $msi -ExpectedSha256 $expectedHash -MicrosoftSignature

    # Instalar silencioso con feature completa
    $msiArgs = @(
        '/i', "`"$msi`"",
        '/qn', '/norestart',
        'ADD_PATH=1',
        'ENABLE_PSREMOTING=0',
        'REGISTER_MANIFEST=1'
    )
    Write-Host "  [>] Instalando MSI (msiexec silencioso)..." -ForegroundColor Cyan
    $p = Invoke-AtlasNativeProcess -FilePath 'msiexec.exe' -Arguments ($msiArgs -join ' ') -TimeoutSeconds 1800 -SuccessCodes @(0,3010)
    if ($p.State -ne 'Correct') { throw "msiexec: $($p.State), exit $($p.ExitCode). Inspect installation state before retrying." }
    if ($p.ExitCode -eq 3010) { Write-Warning 'PowerShell installation requires a Windows restart.' }

    $path = Get-AtlasPS7Path
    if (-not $path) {
        throw "Instalacion reportada OK pero pwsh.exe no se encuentra en las rutas esperadas."
    }
    Write-Host "  [OK] PowerShell 7 instalado: $path" -ForegroundColor Green
    return $path
}

# Cache de la ruta resuelta (lo rellena el launcher al arrancar).
$script:AtlasPS7CachedPath = $null

function Initialize-AtlasPS7 {
    <#
    .SYNOPSIS
      Llamado por el launcher al arrancar para cachear la ruta a pwsh.exe.
      ToolRunner lee $script:AtlasPS7CachedPath para decidir si usa pwsh o powershell.
    #>
    $script:AtlasPS7CachedPath = Get-AtlasPS7Path
    return $script:AtlasPS7CachedPath
}


# ---- lib/Release ----
# Atlas release transport and activation. Shared by get.ps1, launcher and USB.
# Trust starts at the HTTPS bootstrap from the existing Cloudflare domain.
# Cloudflare pins the commit AND manifest digest independently of repository reads.

function Get-AtlasTextHash {
    [CmdletBinding()]
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Text)
    $canonical = $Text.TrimStart([char]0xFEFF).Replace("`r`n", "`n").Replace("`r", "`n")
    $sha = [Security.Cryptography.SHA256]::Create()
    try {
        return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($canonical)))).Replace('-', '').ToLowerInvariant()
    } finally { $sha.Dispose() }
}

function Assert-AtlasReleaseDescriptor {
    [CmdletBinding()]
    param([Parameter(Mandatory)]$Descriptor)
    if ($Descriptor.schemaVersion -ne 1 -or [string]$Descriptor.commit -cnotmatch '^[a-f0-9]{40}$' -or
        [string]$Descriptor.manifestSha256 -cnotmatch '^[a-f0-9]{64}$') {
        throw 'Invalid Atlas publication descriptor. No mutable-ref fallback is permitted.'
    }
}

function Get-AtlasPublishedRelease {
    [CmdletBinding()]
    param()
    $descriptor = Invoke-RestMethod -Uri ('https://toolspanel.atlaspcsupport.com/release.json?v=' + [guid]::NewGuid().ToString('N')) -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop
    Assert-AtlasReleaseDescriptor $descriptor
    return $descriptor
}

function Save-AtlasReleaseFile {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Commit, [Parameter(Mandatory)][string]$RelativePath, [Parameter(Mandatory)][string]$Destination)
    # Every transport fallback is bound to the SAME full commit. Never fall back to main.
    $repository = 'mikepchelper-spec/atlas-pc-support'
    try {
        Invoke-WebRequest -Uri "https://raw.githubusercontent.com/$repository/$Commit/$RelativePath" -OutFile $Destination -UseBasicParsing -TimeoutSec 60 -ErrorAction Stop
    } catch {
        $headers = @{ 'User-Agent' = 'AtlasPCSupport-Release'; Accept = 'application/vnd.github+json' }
        $response = Invoke-RestMethod -Uri "https://api.github.com/repos/$repository/contents/${RelativePath}?ref=$Commit" -Headers $headers -UseBasicParsing -TimeoutSec 60 -ErrorAction Stop
        if ($response.encoding -ne 'base64' -or -not $response.content) { throw 'Commit-bound API download did not contain file bytes.' }
        [IO.File]::WriteAllBytes($Destination, [Convert]::FromBase64String(($response.content -replace '\s', '')))
    }
}

function Assert-AtlasPlainDirectory {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Path)
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if (-not $item.PSIsContainer) { throw "Not a directory: $Path" }
    while ($null -ne $item) {
        if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw "Release paths cannot cross reparse points: $Path" }
        $item = $item.Parent
    }
}

function Test-AtlasRelease {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Directory, [Parameter(Mandatory)][string]$ExpectedManifestSha256)
    Assert-AtlasPlainDirectory $Directory
    if ($ExpectedManifestSha256 -cnotmatch '^[a-f0-9]{64}$') { throw 'A trusted manifest digest is required.' }
    $manifestPath = Join-Path $Directory 'release-manifest.json'
    $manifestItem = Get-Item -LiteralPath $manifestPath -Force -ErrorAction Stop
    if ($manifestItem.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Manifest cannot be a link.' }
    $actual = (Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
    if ($actual -cne $ExpectedManifestSha256) { throw 'Atlas manifest digest mismatch.' }
    $manifest = [IO.File]::ReadAllText($manifestPath, [Text.Encoding]::UTF8) | ConvertFrom-Json -ErrorAction Stop
    if ($manifest.schemaVersion -ne 1 -or $manifest.algorithm -ne 'SHA256-UTF8-LF' -or -not $manifest.version) { throw 'Unsupported Atlas manifest.' }
    $names = @($manifest.files.PSObject.Properties.Name)
    $required = @('get.ps1', 'launcher.ps1', 'config/tools.json', 'config/dependencies.json', 'config/tool-hashes.json', 'onboarding/install.bat')
    # Preserve verification/rollback of earlier complete bundles; new distributions carry their own MIT notice.
    $releaseVersion = $null
    if ([version]::TryParse([string]$manifest.version, [ref]$releaseVersion) -and $releaseVersion -ge [version]'1.5.12') { $required += 'LICENSE' }
    foreach ($name in $required) { if ($names -cnotcontains $name) { throw "Missing release member: $name" } }
    $seen = @{}
    foreach ($entry in $manifest.files.PSObject.Properties) {
        $name = $entry.Name
        if (($required -cnotcontains $name -and $name -cnotmatch '^src/tools/Invoke-[A-Za-z0-9-]+\.ps1$') -or $seen.ContainsKey($name)) {
            throw "Invalid or duplicate release path: $name"
        }
        $seen[$name] = $true
        if ([string]$entry.Value -cnotmatch '^[a-f0-9]{64}$') { throw "Invalid release hash: $name" }
        $file = Join-Path $Directory $name
        Assert-AtlasPlainDirectory (Split-Path -Parent $file)
        $item = Get-Item -LiteralPath $file -Force -ErrorAction Stop
        if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw "Release member is not a plain file: $name" }
        if ($item.Length -gt 10MB) { throw "Oversized release member: $name" }
        if ((Get-AtlasTextHash ([IO.File]::ReadAllText($file, [Text.Encoding]::UTF8))) -cne [string]$entry.Value) { throw "Release member digest mismatch: $name" }
    }
    $tools = @(([IO.File]::ReadAllText((Join-Path $Directory 'config/tools.json'), [Text.Encoding]::UTF8) | ConvertFrom-Json -ErrorAction Stop).tools)
    $toolNames = @{}
    foreach ($tool in $tools) {
        $name = [string]$tool.source
        if ($name -cnotmatch '^Invoke-[A-Za-z0-9-]+\.ps1$' -or $toolNames.ContainsKey($name) -or $names -cnotcontains "src/tools/$name") { throw "Missing or duplicated tool: $name" }
        if ($tool.function -cne [IO.Path]::GetFileNameWithoutExtension($name) -or
            $tool.runtime.engine -notin @('windows-powershell','pwsh') -or $tool.runtime.architecture -ne 'x64' -or
            [string]$tool.runtime.minimumVersion -notmatch '^\d+\.\d+(?:\.\d+){0,2}$' -or @($tool.runtime.libraries).Count -eq 0) { throw "Missing tool execution contract: $name" }
        foreach ($library in @($tool.runtime.libraries)) { if ($library -notin @('ToolKit','Dependencies','PS7','Release','Reports','Operations')) { throw "Unknown tool library: $library" } }
        $toolNames[$name] = $true
    }
    if ($tools.Count -eq 0 -or $names.Count -ne ($required.Count + $tools.Count)) { throw 'Release members and tool manifest do not match.' }
    return $manifest
}

function Get-AtlasInstalledRelease {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Root, [switch]$Previous)
    $pointerFile = if ($Previous) { 'previous.json' } else { 'current.json' }
    Assert-AtlasPlainDirectory $Root
    $pointerPath = Join-Path $Root $pointerFile
    if ((Get-Item -LiteralPath $pointerPath -Force -ErrorAction Stop).Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Release pointer cannot be a link.' }
    $pointer = [IO.File]::ReadAllText($pointerPath, [Text.Encoding]::UTF8) | ConvertFrom-Json -ErrorAction Stop
    Assert-AtlasReleaseDescriptor $pointer
    if ([string]$pointer.directory -cnotmatch '^[a-f0-9]{40}(?:-[a-f0-9]{32})?$') { throw 'Invalid installed release directory.' }
    if (-not ([string]$pointer.directory).StartsWith([string]$pointer.commit, [StringComparison]::Ordinal)) { throw 'Release directory and commit differ.' }
    $directory = Join-Path (Join-Path $Root 'releases') $pointer.directory
    $manifest = Test-AtlasRelease -Directory $directory -ExpectedManifestSha256 $pointer.manifestSha256
    return [pscustomobject]@{ Directory = $directory; Commit = $pointer.commit; ManifestSha256 = $pointer.manifestSha256; Manifest = $manifest }
}

function Set-AtlasReleasePointer {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Root, [Parameter(Mandatory)]$Release)
    $pointer = [ordered]@{ schemaVersion = 1; commit = $Release.Commit; manifestSha256 = $Release.ManifestSha256; directory = Split-Path -Leaf $Release.Directory }
    $current = Join-Path $Root 'current.json'
    $temporary = Join-Path $Root ('pointer-' + [guid]::NewGuid().ToString('N') + '.tmp')
    try {
        $bytes = [Text.Encoding]::UTF8.GetBytes(($pointer | ConvertTo-Json -Compress))
        $stream = [IO.FileStream]::new($temporary, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
        try { $stream.Write($bytes, 0, $bytes.Length); $stream.Flush($true) } finally { $stream.Dispose() }
        if (Test-Path -LiteralPath $current) {
            # Same-volume atomic replacement. If unsupported, leave the current release alone.
            [IO.File]::Replace($temporary, $current, (Join-Path $Root 'previous.json'), $true)
        } else { [IO.File]::Move($temporary, $current) }
    } finally {
        if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary -Force -ErrorAction Stop }
    }
}

function Install-AtlasRelease {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Root, [Parameter(Mandatory)]$Descriptor, [string]$SourceDirectory, [switch]$PrepareOfflineEntry)
    Assert-AtlasReleaseDescriptor $Descriptor
    if (-not (Test-Path -LiteralPath $Root)) { New-Item -ItemType Directory -Path $Root -ErrorAction Stop | Out-Null }
    Assert-AtlasPlainDirectory $Root
    $releases = Join-Path $Root 'releases'
    if (-not (Test-Path -LiteralPath $releases)) { New-Item -ItemType Directory -Path $releases -ErrorAction Stop | Out-Null }
    Assert-AtlasPlainDirectory $releases
    $lock = [IO.FileStream]::new((Join-Path $Root '.update.lock'), [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite, [IO.FileShare]::None)
    $stage = Join-Path $releases ('.staging-' + [guid]::NewGuid().ToString('N'))
    try {
        try {
            $current = Get-AtlasInstalledRelease -Root $Root
            if ($current.Commit -ceq $Descriptor.commit -and $current.ManifestSha256 -ceq $Descriptor.manifestSha256) {
                if ($PrepareOfflineEntry) { Initialize-AtlasOfflineEntry -Root $Root -Release $current }
                return $current
            }
        } catch { Write-Verbose "No matching verified current release: $_" }
        New-Item -ItemType Directory -Path $stage -ErrorAction Stop | Out-Null
        $manifestPath = Join-Path $stage 'release-manifest.json'
        if ($SourceDirectory) {
            Test-AtlasRelease -Directory $SourceDirectory -ExpectedManifestSha256 $Descriptor.manifestSha256 | Out-Null
            Copy-Item -LiteralPath (Join-Path $SourceDirectory 'release-manifest.json') -Destination $manifestPath -ErrorAction Stop
        } else {
            Save-AtlasReleaseFile -Commit $Descriptor.commit -RelativePath 'release-manifest.json' -Destination $manifestPath
        }
        if ((Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant() -cne $Descriptor.manifestSha256) { throw 'Downloaded manifest is not the approved publication.' }
        $manifest = [IO.File]::ReadAllText($manifestPath, [Text.Encoding]::UTF8) | ConvertFrom-Json -ErrorAction Stop
        if ($manifest.schemaVersion -ne 1 -or $manifest.algorithm -ne 'SHA256-UTF8-LF') { throw 'Unsupported release manifest.' }
        foreach ($entry in $manifest.files.PSObject.Properties) {
            $name = $entry.Name
            if ($name -cnotmatch '^(get\.ps1|launcher\.ps1|LICENSE|onboarding/install\.bat|config/(tools|dependencies|tool-hashes)\.json|src/tools/Invoke-[A-Za-z0-9-]+\.ps1)$') { throw "Unsafe release path: $name" }
            $destination = Join-Path $stage $name
            $parent = Split-Path -Parent $destination
            if (-not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Path $parent -Force -ErrorAction Stop | Out-Null }
            if ($SourceDirectory) { Copy-Item -LiteralPath (Join-Path $SourceDirectory $name) -Destination $destination -ErrorAction Stop }
            else { Save-AtlasReleaseFile -Commit $Descriptor.commit -RelativePath $name -Destination $destination }
        }
        $verified = Test-AtlasRelease -Directory $stage -ExpectedManifestSha256 $Descriptor.manifestSha256
        $name = [string]$Descriptor.commit
        $destination = Join-Path $releases $name
        if (Test-Path -LiteralPath $destination) { $destination = Join-Path $releases ($name + '-' + [guid]::NewGuid().ToString('N')) }
        [IO.Directory]::Move($stage, $destination)
        $release = [pscustomobject]@{ Directory = $destination; Commit = $Descriptor.commit; ManifestSha256 = $Descriptor.manifestSha256; Manifest = $verified }
        if ($PrepareOfflineEntry) { Initialize-AtlasOfflineEntry -Root $Root -Release $release }
        Set-AtlasReleasePointer -Root $Root -Release $release
        return $release
    } finally {
        $lock.Dispose()
        if (Test-Path -LiteralPath $stage) {
            # This GUID child was created above, under the already checked releases directory.
            Assert-AtlasPlainDirectory $stage
            if ([IO.Path]::GetFullPath((Split-Path -Parent $stage)) -ne [IO.Path]::GetFullPath($releases) -or (Split-Path -Leaf $stage) -notmatch '^\.staging-[a-f0-9]{32}$') { throw 'Unsafe staging cleanup refused.' }
            Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction Stop
        }
    }
}

function Restore-AtlasPreviousRelease {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Root)
    Assert-AtlasPlainDirectory $Root
    $lock = [IO.FileStream]::new((Join-Path $Root '.update.lock'), [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite, [IO.FileShare]::None)
    try {
        $previous = Get-AtlasInstalledRelease -Root $Root -Previous
        Set-AtlasReleasePointer -Root $Root -Release $previous
        return $previous
    } finally { $lock.Dispose() }
}

function Initialize-AtlasOfflineEntry {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Root, [Parameter(Mandatory)]$Release)
    Assert-AtlasPlainDirectory $Root
    Test-AtlasRelease -Directory $Release.Directory -ExpectedManifestSha256 $Release.ManifestSha256 | Out-Null
    # A generic offline entry; never refresh individual components on startup.
    $entry = Join-Path $Root 'get.ps1'
    $temporary = Join-Path $Root ('entry-' + [guid]::NewGuid().ToString('N') + '.tmp')
    try {
        [IO.File]::WriteAllText($temporary, [IO.File]::ReadAllText((Join-Path $Release.Directory 'get.ps1'), [Text.Encoding]::UTF8), [Text.UTF8Encoding]::new($true))
        if (Test-Path -LiteralPath $entry) { [IO.File]::Replace($temporary, $entry, (Join-Path $Root 'get.previous.ps1'), $true) }
        else { [IO.File]::Move($temporary, $entry) }
    } finally {
        if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary -Force -ErrorAction Stop }
    }
    $bat = @('@echo off', 'setlocal', 'cd /d "%~dp0"', 'powershell.exe -NoProfile -Sta -ExecutionPolicy RemoteSigned -File "%~dp0get.ps1" -OfflineRoot "%~dp0."', 'set "RC=%errorlevel%"', 'if not "%RC%"=="0" pause', 'exit /b %RC%') -join "`r`n"
    [IO.File]::WriteAllText((Join-Path $Root 'run.bat'), $bat + "`r`n", [Text.Encoding]::ASCII)
}

function Start-AtlasRelease {
    [CmdletBinding()]
    param([Parameter(Mandatory)]$Release, [string]$OfflineAssetsRoot = '')
    Assert-AtlasReleaseDescriptor ([pscustomobject]@{ schemaVersion=1; commit=$Release.Commit; manifestSha256=$Release.ManifestSha256 })
    Test-AtlasRelease -Directory $Release.Directory -ExpectedManifestSha256 $Release.ManifestSha256 | Out-Null
    $engine = Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe'
    if ([Environment]::Is64BitOperatingSystem -and -not [Environment]::Is64BitProcess) { $engine = Join-Path $env:SystemRoot 'Sysnative/WindowsPowerShell/v1.0/powershell.exe' }
    if (-not [Environment]::Is64BitOperatingSystem -or -not (Test-Path -LiteralPath $engine)) { throw 'Atlas requires Windows PowerShell 5.1 x64.' }
    $arguments = @('-NoProfile','-Sta','-ExecutionPolicy','RemoteSigned','-File', ('"{0}"' -f (Join-Path $Release.Directory 'launcher.ps1')), '-AtlasReleaseCommit',$Release.Commit,'-AtlasManifestSha256',$Release.ManifestSha256)
    # PS 5.1 drops empty native arguments. Omit an absent optional path entirely.
    if ($OfflineAssetsRoot) { $arguments += @('-AtlasOfflineRoot', ('"{0}"' -f $OfflineAssetsRoot)) }
    $process = Start-Process -FilePath $engine -ArgumentList $arguments -NoNewWindow -Wait -PassThru -ErrorAction Stop
    if ($process.ExitCode -ne 0) { throw "Atlas launcher exited with code $($process.ExitCode)." }
}


# ---- lib/Capabilities ----
# Platform facts are collected read-only. Build and capabilities, never ProductName alone.
function Resolve-AtlasPlatform {
    [CmdletBinding()]
    param([int]$Build, [string]$EditionId, [int]$ProductType = 1, [string]$Architecture, [string[]]$Commands = @())
    $client = $ProductType -eq 1
    $baseline = $client -and $Build -ge 19044 -and $Architecture -eq 'x64'
    $is11 = $client -and $Build -ge 22000
    $ltsc = $EditionId -match 'EnterpriseS|IoTEnterpriseS'
    [pscustomobject]@{
        Build=$Build; EditionId=$EditionId; Architecture=$Architecture; Client=$client
        Windows11=$is11; LTSC=$ltsc; Baseline=$baseline
        SupportProfile= $(if (-not $baseline) {'Outside tested target'} elseif ($ltsc) {'LTSC capability-dependent'} elseif ($is11) {'Windows 11'} else {'Windows 10 22H2/LTSC target; VM qualification pending'})
        NativeDoh=($is11 -and $Commands -contains 'Get-DnsClientDohServerAddress' -and $Commands -contains 'Set-DnsClientDohServerAddress')
        BitLocker=($EditionId -notmatch '^Core' -and $Commands -contains 'Get-BitLockerVolume' -and $Commands -contains 'Enable-BitLocker')
        Commands=@($Commands)
    }
}

function Get-AtlasPlatformCapabilities {
    [CmdletBinding()]
    param([switch]$Refresh)
    if ($script:AtlasPlatformCapabilities -and -not $Refresh) { return $script:AtlasPlatformCapabilities }
    $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
    $edition = (Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -Name EditionID -ErrorAction Stop).EditionID
    $architecture = if ($env:PROCESSOR_ARCHITEW6432) { $env:PROCESSOR_ARCHITEW6432 } else { $env:PROCESSOR_ARCHITECTURE }
    $architecture = switch ($architecture) { 'AMD64' {'x64'} 'ARM64' {'arm64'} default {'x86'} }
    $names = @('Get-CimInstance','Get-WinEvent','Get-NetAdapter','Get-DnsClientServerAddress','Set-DnsClientServerAddress','Get-DnsClientDohServerAddress','Set-DnsClientDohServerAddress','Get-BitLockerVolume','Enable-BitLocker','Get-LocalUser','Get-LocalGroupMember','Get-AppxPackage','Add-AppxPackage','Get-WindowsOptionalFeature','Enable-WindowsOptionalFeature','Export-WindowsDriver','robocopy.exe','netsh.exe','dism.exe','sfc.exe')
    $available = @($names | Where-Object { Get-Command $_ -ErrorAction SilentlyContinue })
    $script:AtlasPlatformCapabilities = Resolve-AtlasPlatform -Build ([int]$os.BuildNumber) -EditionId $edition -ProductType ([int]$os.ProductType) -Architecture $architecture -Commands $available
    return $script:AtlasPlatformCapabilities
}

function Test-AtlasToolAvailability {
    [CmdletBinding()]
    param([Parameter(Mandatory)][hashtable]$Tool, $Capabilities)
    if (-not $Capabilities) { $Capabilities = Get-AtlasPlatformCapabilities }
    $reasons = @()
    if ($Tool.availability -and $Tool.availability.disabledReason) { $reasons += [string]$Tool.availability.disabledReason }
    if (-not $Capabilities.Baseline) { $reasons += 'Requires a Windows client build 19044+ on x64; this platform is outside the current target.' }
    if ($Tool.availability.minimumBuild -and $Capabilities.Build -lt [int]$Tool.availability.minimumBuild) { $reasons += "Requires build $($Tool.availability.minimumBuild) or newer." }
    foreach ($name in @($Tool.availability.commands)) {
        if ($name -and $Capabilities.Commands -notcontains $name) { $reasons += "Missing Windows capability: $name" }
    }
    if ($Tool.id -eq 'gestor-bitlocker' -and -not $Capabilities.BitLocker) { $reasons += 'Full BitLocker management is unavailable for this edition/modules. Device Encryption is managed in Windows Settings.' }
    [pscustomobject]@{ Available=($reasons.Count -eq 0); Reason=($reasons -join ' '); Profile=$Capabilities.SupportProfile }
}

function Get-AtlasPackageMinimumBuild {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Id)
    # Explicit MinimumOSVersion values in the 2026-10-25 manifest snapshot.
    # A missing value is unknown, not a claim of Windows 10 vendor support.
    switch ($Id) {
        'Notion.Notion' { return 19041 }
        'Learneo.LanguageTool' { return 19041 }
        'LanguageToolGmbH.LanguageToolForDesktop' { return 19041 }
        'Microsoft.Teams' { return 17763 }
        'Microsoft.PowerToys' { return 17134 }
        'Microsoft.PowerShell' { return 17763 }
        'Microsoft.WindowsTerminal' { return 19041 }
        default { return $null }
    }
}

function Assert-AtlasPackageRequest {
    [CmdletBinding()]
    param([Parameter(Mandatory)]$Package, [int]$Build)
    if ($Package.Type -eq 'Action') { throw 'Maintenance actions cannot be installed as packages.' }
    if ([string]$Package.Id -cnotmatch '^[A-Za-z0-9][A-Za-z0-9._+-]{0,199}$') { throw 'Invalid package identifier; options and whitespace are not allowed.' }
    if ($Package.Source -and $Package.Source -cnotin @('winget','msstore')) { throw 'Unsupported package source.' }
    if ($Build -lt 19044) { throw 'Package installation is outside the supported Windows baseline.' }
    $knownMinimum = Get-AtlasPackageMinimumBuild -Id ([string]$Package.Id)
    $minimum = [Math]::Max([int]$knownMinimum, [int]$Package.MinimumBuild)
    if ($Build -lt $minimum) { throw 'Package requires a newer Windows build.' }
}

function Get-AtlasStoreState {
    [CmdletBinding()]
    param()
    $platform = Get-AtlasPlatformCapabilities
    $store = $null; $provisioned = $null; $errorMessage = $null
    try { $store = Get-AppxPackage -Name Microsoft.WindowsStore -ErrorAction Stop } catch { $errorMessage=$_.Exception.Message }
    if (-not $store) {
        try { $provisioned = @(Get-AppxPackage -AllUsers -Name Microsoft.WindowsStore -ErrorAction Stop) | Select-Object -First 1 }
        catch { $errorMessage=$_.Exception.Message }
    }
    $blocked = $false
    foreach ($path in @('HKLM:\SOFTWARE\Policies\Microsoft\WindowsStore','HKCU:\SOFTWARE\Policies\Microsoft\WindowsStore')) {
        if (Test-Path -LiteralPath $path) {
            $policy = Get-ItemProperty -LiteralPath $path -ErrorAction Stop
            if ($policy.RemoveWindowsStore -eq 1 -or $policy.DisableStoreApps -eq 1) { $blocked=$true }
        }
    }
    $appInstaller = $null
    try { $appInstaller=Get-AppxPackage -Name Microsoft.DesktopAppInstaller -ErrorAction Stop } catch { $errorMessage=$_.Exception.Message }
    [pscustomobject]@{
        State=$(if($blocked){'BlockedByPolicy'} elseif($store){'RegisteredForCurrentUser'} elseif($provisioned){'PresentNotRegisteredForCurrentUser'} elseif($errorMessage){'NotEvaluated'} else {'NotInstalled'})
        Store=$store; ExistingPackage=$provisioned; AppInstaller=$appInstaller
        WingetAvailable=[bool](Get-Command winget.exe -ErrorAction SilentlyContinue)
        LTSC=$platform.LTSC; Error=$errorMessage
    }
}


# ---- lib/Operations ----
# Small shared primitives for evidence and reversible Windows operations.
function Assert-AtlasCopyDestination {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Source,[Parameter(Mandatory)][string]$Destination)
    $origin=[IO.Path]::GetFullPath($Source).TrimEnd([char[]]'\/')
    $target=[IO.Path]::GetFullPath($Destination).TrimEnd([char[]]'\/')
    if($target.Equals($origin,[StringComparison]::OrdinalIgnoreCase) -or
        $target.StartsWith($origin+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'Copy destination cannot be the source or a child of the source.'}
    $item=Get-Item -LiteralPath ([IO.Path]::GetFullPath($Source)) -Force -ErrorAction Stop
    if ($item.PSIsContainer) { Assert-AtlasPlainDirectory $item.FullName }
    else {
        Assert-AtlasPlainFile $item.FullName
        if ((Join-Path ([IO.Path]::GetFullPath($Destination)) $item.Name).Equals($item.FullName,[StringComparison]::OrdinalIgnoreCase)) { throw 'Copy destination would overwrite the source file itself.' }
    }
    $parent=[IO.Path]::GetFullPath($Destination)
    while (-not (Test-Path -LiteralPath $parent)) {
        $parent=[IO.Path]::GetDirectoryName($parent)
        if (-not $parent) { throw 'Copy destination has no existing parent directory.' }
    }
    Assert-AtlasPlainDirectory $parent
}

function ConvertTo-AtlasNativeArgument {
    [CmdletBinding()]
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Value)
    if ($Value.IndexOf([char]0) -ge 0 -or $Value -match '[\r\n]') { throw 'Native arguments cannot contain NUL or newlines.' }
    $escaped = [regex]::Replace($Value, '(\\*)"', '$1$1\"')
    $escaped = [regex]::Replace($escaped, '(\\+)$', '$1$1')
    return '"' + $escaped + '"'
}

function Stop-AtlasOwnedNativeProcess {
    [CmdletBinding()]
    param([Parameter(Mandatory)][Diagnostics.Process]$Process)
    if ($Process.HasExited) { return }
    if ($env:OS -eq 'Windows_NT') {
        $info = [Diagnostics.ProcessStartInfo]::new()
        $info.FileName = [IO.Path]::Combine($env:SystemRoot, 'System32\taskkill.exe')
        $info.Arguments = "/PID $($Process.Id) /T /F"
        $info.UseShellExecute = $false; $info.CreateNoWindow = $true
        $info.RedirectStandardOutput = $true; $info.RedirectStandardError = $true
        $stopper = [Diagnostics.Process]::Start($info)
        try {
            $output = $stopper.StandardOutput.ReadToEndAsync(); $errorOutput = $stopper.StandardError.ReadToEndAsync()
            if (-not $stopper.WaitForExit(5000)) { $stopper.Kill(); throw 'Owned process tree termination timed out.' }
            if ($stopper.ExitCode -ne 0 -and -not $Process.HasExited) { throw 'Owned process tree termination failed.' }
            [void]$output.Wait(1000); [void]$errorOutput.Wait(1000)
        } finally { $stopper.Dispose() }
    } else { $Process.Kill($true) }
    if (-not $Process.WaitForExit(5000)) { throw 'Owned process could not be stopped; inspect manually.' }
}

function Invoke-AtlasNativeProcess {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$FilePath,[string]$Arguments='',
        [string[]]$ArgumentList, [string]$WorkingDirectory,
        [ValidateRange(1,86400)][int]$TimeoutSeconds=600,[int[]]$SuccessCodes=@(0),
        [Threading.CancellationToken]$CancellationToken = [Threading.CancellationToken]::None,
        [switch]$NoCapture)
    if ($PSBoundParameters.ContainsKey('ArgumentList') -and $PSBoundParameters.ContainsKey('Arguments')) { throw 'Choose ArgumentList or raw Arguments, not both.' }
    if ($PSBoundParameters.ContainsKey('ArgumentList')) { $Arguments = (@($ArgumentList | ForEach-Object { ConvertTo-AtlasNativeArgument $_ }) -join ' ') }
    if ($CancellationToken.IsCancellationRequested) {
        return [pscustomobject]@{State='Cancelled';Started=$false;Completed=$false;Cancelled=$true;TimedOut=$false;ExitCode=$null;Stdout='';Stderr='';DurationSeconds=0;OutputCaptured=$false}
    }
    $info=[Diagnostics.ProcessStartInfo]::new()
    $info.FileName=$FilePath; $info.Arguments=$Arguments
    if ($WorkingDirectory) { $info.WorkingDirectory = $WorkingDirectory }
    $info.UseShellExecute=$false; $info.CreateNoWindow=$true
    $info.RedirectStandardOutput=-not $NoCapture; $info.RedirectStandardError=-not $NoCapture
    $watch=[Diagnostics.Stopwatch]::StartNew(); $process=$null
    try {
        $process=[Diagnostics.Process]::Start($info)
        $stdout=$null; $stderr=$null; $cancelled=$false; $timedOut=$false
        if (-not $NoCapture) { $stdout=$process.StandardOutput.ReadToEndAsync(); $stderr=$process.StandardError.ReadToEndAsync() }
        while (-not $process.WaitForExit(100)) {
            if ($CancellationToken.IsCancellationRequested) { $cancelled=$true; break }
            if ($watch.Elapsed.TotalSeconds -ge $TimeoutSeconds) { $timedOut=$true; break }
        }
        if ($cancelled -or $timedOut) { Stop-AtlasOwnedNativeProcess -Process $process }
        $captured=$NoCapture -or ($stdout.Wait(3000) -and $stderr.Wait(3000))
        [pscustomobject]@{State=$(if($cancelled){'Cancelled'}elseif($timedOut){'TimedOut'}elseif(-not $captured){'NotEvaluated'}elseif($SuccessCodes -contains $process.ExitCode){'Correct'}else{'Failed'});Started=$true;Completed=(-not($timedOut -or $cancelled));Cancelled=$cancelled;ExitCode=$process.ExitCode;TimedOut=$timedOut;Stdout=$(if($stdout -and $stdout.IsCompleted){$stdout.Result}else{''});Stderr=$(if($stderr -and $stderr.IsCompleted){$stderr.Result}else{''});DurationSeconds=$watch.Elapsed.TotalSeconds;OutputCaptured=([bool]$captured -and -not $NoCapture)}
    } finally {
        $watch.Stop()
        if($process){
            try { if (-not $process.HasExited) { Stop-AtlasOwnedNativeProcess -Process $process } }
            finally { $process.Dispose() }
        }
    }
}

function Test-AtlasCopySample {
    [CmdletBinding()]
    param([string]$Source,[string]$Destination,[ValidateRange(1,1000)][int]$SampleSize=15,[string[]]$ExcludeFiles=@(),[string[]]$ExcludeDirs=@())
    $sourceItem=Get-Item -LiteralPath $Source -Force -ErrorAction Stop
    $sourceRoot=if($sourceItem.PSIsContainer){$sourceItem.FullName}else{$sourceItem.DirectoryName}
    Assert-AtlasPlainDirectory $sourceRoot
    $files=[Collections.Generic.List[IO.FileInfo]]::new(); $links=0
    $pending=[Collections.Generic.Stack[IO.FileSystemInfo]]::new();$pending.Push($sourceItem)
    while ($pending.Count) {
        $item=$pending.Pop()
        $isDirectory=$item -is [IO.DirectoryInfo]
        $patterns=if($isDirectory -and $item.FullName -ne $sourceItem.FullName){$ExcludeDirs}elseif(-not $isDirectory){$ExcludeFiles}else{@()}
        $excluded=$false
        foreach($pattern in $patterns){if($item.Name -like $pattern){$excluded=$true;break}}
        if($excluded){continue}
        if($item.Attributes -band [IO.FileAttributes]::ReparsePoint){$links++;continue}
        if($isDirectory){
            Assert-AtlasPlainDirectory $item.FullName
            foreach($child in @(Get-ChildItem -LiteralPath $item.FullName -Force -ErrorAction Stop)){$pending.Push($child)}
        }else{$files.Add($item)}
    }
    if($files.Count -eq 0){return @{OK=$false;State='NotEvaluated';Coverage='No eligible plain source files';Checked=0;Passed=0;Failed=0;Missing=0;UnverifiedLinks=$links}}
    $sample=@($files.ToArray() | Sort-Object FullName | Select-Object -First $SampleSize)
    $passed=0;$failed=0;$missing=0
    foreach($file in $sample){
        $relative=$file.FullName.Substring($sourceRoot.Length).TrimStart([char[]]'\/')
        $target=Join-Path $Destination $relative
        if(-not(Test-Path -LiteralPath $target -PathType Leaf)){$missing++;continue}
        try{
            Assert-AtlasPlainFile $file.FullName; Assert-AtlasPlainFile $target
            if((Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256 -ErrorAction Stop).Hash -eq (Get-FileHash -LiteralPath $target -Algorithm SHA256 -ErrorAction Stop).Hash){$passed++}else{$failed++}
        }catch{$failed++}
    }
    @{OK=($failed -eq 0 -and $missing -eq 0 -and $links -eq 0);State=$(if($failed -or $missing){'Failed'}elseif($links){'NotEvaluated'}else{'SampleVerified'});Coverage="SHA256 sample $($sample.Count)/$($files.Count) eligible plain files; $links links not evaluated; not full copy certification";Checked=$sample.Count;Passed=$passed;Failed=$failed;Missing=$missing;UnverifiedLinks=$links}
}

function Remove-AtlasHostsAlias {
    [CmdletBinding()]
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Text,[Parameter(Mandatory)][string]$Hostname)
    if($Hostname -notmatch '^(?=.{1,253}$)[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?$'){throw 'Invalid exact hosts name.'}
    $lines=foreach($line in ($Text -split '\r?\n')){
        $parts=$line -split '#',2; $tokens=@($parts[0].Trim() -split '\s+' | Where-Object {$_})
        if($tokens.Count -lt 2 -or $tokens[1..($tokens.Count-1)] -inotcontains $Hostname){$line;continue}
        $aliases=@($tokens[1..($tokens.Count-1)] | Where-Object {$_ -ine $Hostname})
        if($aliases.Count){$tokens[0]+"`t"+($aliases -join ' ')+$(if($parts.Count -gt 1){' #'+$parts[1]}else{''})}
        elseif($parts.Count -gt 1){'#'+$parts[1]}
    }
    return $lines -join "`r`n"
}

function Set-AtlasHostsText {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Path,[Parameter(Mandatory)][AllowEmptyString()][string]$Text)
    $item=Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if($item.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Hosts file cannot be a link.'}
    Assert-AtlasPlainDirectory (Split-Path -Parent $item.FullName)
    $before=[IO.File]::ReadAllBytes($item.FullName)
    $backup=$item.FullName+'.atlas-'+[guid]::NewGuid().ToString('N')+'.bak'
    $temp=$item.FullName+'.atlas-'+[guid]::NewGuid().ToString('N')+'.tmp'
    try{
        [IO.File]::WriteAllBytes($backup,$before)
        if([Convert]::ToBase64String([IO.File]::ReadAllBytes($backup)) -cne [Convert]::ToBase64String($before)){throw 'Hosts backup readback failed.'}
        [IO.File]::WriteAllText($temp,$Text,[Text.UTF8Encoding]::new($false))
        [IO.File]::Replace($temp,$item.FullName,$backup+'.replace',$true)
        if([IO.File]::ReadAllText($item.FullName,[Text.Encoding]::UTF8) -cne $Text){throw 'Hosts write could not be verified; restore the backup.'}
        return $backup
    }finally{if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Force -ErrorAction Stop}}
}

function Clear-AtlasPrintQueue {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$PrinterName)
    # Remove only the selected queue's jobs. Never stop Spooler and delete every queue.
    $printer=Get-Printer -Name $PrinterName -ErrorAction Stop
    if(-not $printer){throw 'Selected printer is unavailable.'}
    $jobs=@(Get-PrintJob -PrinterName $PrinterName -ErrorAction Stop)
    foreach($job in $jobs){Remove-PrintJob -PrinterName $PrinterName -ID $job.ID -ErrorAction Stop}
    $remaining=@(Get-PrintJob -PrinterName $PrinterName -ErrorAction Stop)
    if(@($remaining | Where-Object {$jobs.ID -contains $_.ID}).Count){throw 'Some selected jobs remain; queue clearing was incomplete.'}
    return $jobs.Count
}

function Save-AtlasDnsSnapshot {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string[]]$AdapterNames,[Parameter(Mandatory)][string]$Path)
    $rows=foreach($name in $AdapterNames){
        $adapter=Get-NetAdapter -Name $name -ErrorAction Stop
        foreach($family in @('IPv4','IPv6')){
            $row=Get-DnsClientServerAddress -InterfaceIndex $adapter.ifIndex -AddressFamily $family -ErrorAction Stop
            if(-not $row){throw "Missing DNS row for $name/$family"}
            $service=if($family -eq 'IPv4'){'Tcpip'}else{'Tcpip6'}
            $key="HKLM:\SYSTEM\CurrentControlSet\Services\$service\Parameters\Interfaces\$(([guid]$adapter.InterfaceGuid).ToString('B'))"
            $properties=Get-ItemProperty -LiteralPath $key -ErrorAction Stop
            [pscustomobject]@{Guid=[string]$adapter.InterfaceGuid;Family=$family;Automatic=[string]::IsNullOrWhiteSpace([string]$properties.NameServer);Servers=@($row.ServerAddresses)}
        }
    }
    $envelope=[ordered]@{SchemaVersion=1;CreatedUtc=[datetime]::UtcNow.ToString('o');Adapters=@($rows)}
    [IO.File]::WriteAllText($Path,($envelope|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
    $read=[IO.File]::ReadAllText($Path,[Text.Encoding]::UTF8)|ConvertFrom-Json -ErrorAction Stop
    if($read.SchemaVersion -ne 1 -or @($read.Adapters).Count -ne @($rows).Count){throw 'DNS snapshot readback failed; no mutation is allowed.'}
    return $Path
}

function Restore-AtlasDnsSnapshot {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Path)
    $snapshot=[IO.File]::ReadAllText($Path,[Text.Encoding]::UTF8)|ConvertFrom-Json -ErrorAction Stop
    if($snapshot.SchemaVersion -ne 1 -or @($snapshot.Adapters).Count -eq 0){throw 'Unsupported DNS backup. Legacy backups do not preserve DHCP/static origin.'}
    # Validate the entire snapshot before the first mutation.
    foreach($entry in $snapshot.Adapters){
        $parsedGuid=[guid]::Empty
        if($entry.Family -notin @('IPv4','IPv6') -or $entry.Automatic -isnot [bool] -or -not [guid]::TryParse([string]$entry.Guid,[ref]$parsedGuid)){throw 'Invalid DNS snapshot row.'}
        foreach($address in @($entry.Servers)){ $ip=$null; if(-not [Net.IPAddress]::TryParse([string]$address,[ref]$ip)){throw 'Invalid DNS address in snapshot.'} }
        if(-not $entry.Automatic -and @($entry.Servers).Count -eq 0){throw 'Static DNS snapshot lacks addresses.'}
    }
    foreach($entry in $snapshot.Adapters){
        $adapter=Get-NetAdapter -ErrorAction Stop | Where-Object {[string]$_.InterfaceGuid -eq [string]$entry.Guid}
        if(@($adapter).Count -ne 1){throw "DNS adapter cannot be identified: $($entry.Guid)"}
        $row=Get-DnsClientServerAddress -InterfaceIndex $adapter.ifIndex -AddressFamily $entry.Family -ErrorAction Stop
        if($entry.Automatic){Set-DnsClientServerAddress -InputObject $row -ResetServerAddresses -ErrorAction Stop}
        else{Set-DnsClientServerAddress -InputObject $row -ServerAddresses @($entry.Servers) -ErrorAction Stop}
        $after=Get-DnsClientServerAddress -InterfaceIndex $adapter.ifIndex -AddressFamily $entry.Family -ErrorAction Stop
        if(-not $entry.Automatic -and (@($after.ServerAddresses)-join ',') -ne (@($entry.Servers)-join ',')){throw 'DNS static restoration could not be verified.'}
        $service=if($entry.Family -eq 'IPv4'){'Tcpip'}else{'Tcpip6'}
        $key="HKLM:\SYSTEM\CurrentControlSet\Services\$service\Parameters\Interfaces\$(([guid]$adapter.InterfaceGuid).ToString('B'))"
        $origin=Get-ItemProperty -LiteralPath $key -ErrorAction Stop
        if($entry.Automatic -and -not [string]::IsNullOrWhiteSpace([string]$origin.NameServer)){throw 'Automatic DNS restoration could not be verified.'}
    }
}

function Get-AtlasServiceSnapshot {
    [CmdletBinding()]
    param([Parameter(Mandatory)][ValidatePattern('^[A-Za-z0-9_-]+$')][string]$Name)
    $service=Get-Service -Name $Name -ErrorAction Stop
    if($service.Status.ToString() -notin @('Running','Stopped')){throw 'Wait for the service to reach a stable state.'}
    if(@($service.DependentServices | Where-Object Status -ne 'Stopped').Count){throw 'Running dependents exist. Atlas will not force-stop them.'}
    $cim=Get-CimInstance -ClassName Win32_Service -Filter "Name='$Name'" -ErrorAction Stop
    if($cim.StartMode -notin @('Auto','Manual','Disabled')){throw 'Unknown startup mode; no change allowed.'}
    $key="HKLM:\SYSTEM\CurrentControlSet\Services\$Name"
    $properties=Get-ItemProperty -LiteralPath $key -ErrorAction Stop
    $delayed=$properties.PSObject.Properties['DelayedAutostart']
    [pscustomobject]@{SchemaVersion=1;Name=$Name;Status=$service.Status.ToString();StartMode=$cim.StartMode;DelayedPresent=($null -ne $delayed);DelayedValue=$(if($delayed){[int]$delayed.Value}else{0})}
}

function Restore-AtlasServiceSnapshot {
    [CmdletBinding()]
    param([Parameter(Mandatory)]$Snapshot)
    if($Snapshot.SchemaVersion -ne 1 -or $Snapshot.Name -notmatch '^[A-Za-z0-9_-]+$' -or $Snapshot.Status -notin @('Running','Stopped') -or $Snapshot.StartMode -notin @('Auto','Manual','Disabled') -or $Snapshot.DelayedPresent -isnot [bool]){throw 'Invalid service snapshot.'}
    $name=$Snapshot.Name
    $mode=@{Auto='Automatic';Manual='Manual';Disabled='Disabled'}[$Snapshot.StartMode]
    # A running service can legitimately have Disabled startup. Restore runtime first.
    if($Snapshot.Status -eq 'Running'){
        if((Get-Service -Name $name -ErrorAction Stop).Status -ne 'Running'){
            Set-Service -Name $name -StartupType Manual -ErrorAction Stop
            Start-Service -Name $name -ErrorAction Stop
        }
    }elseif((Get-Service -Name $name -ErrorAction Stop).Status -ne 'Stopped'){
        Stop-Service -Name $name -ErrorAction Stop
    }
    Set-Service -Name $name -StartupType $mode -ErrorAction Stop
    $key="HKLM:\SYSTEM\CurrentControlSet\Services\$name"
    if($Snapshot.DelayedPresent){Set-ItemProperty -LiteralPath $key -Name DelayedAutostart -Value $Snapshot.DelayedValue -Type DWord -ErrorAction Stop}
    elseif((Get-ItemProperty -LiteralPath $key -ErrorAction Stop).PSObject.Properties['DelayedAutostart']){Remove-ItemProperty -LiteralPath $key -Name DelayedAutostart -ErrorAction Stop}
    $after=Get-Service -Name $name -ErrorAction Stop
    $cim=Get-CimInstance -ClassName Win32_Service -Filter "Name='$name'" -ErrorAction Stop
    if($after.Status.ToString() -ne $Snapshot.Status -or $cim.StartMode -ne $Snapshot.StartMode){throw 'Service restoration could not be verified.'}
    $properties=Get-ItemProperty -LiteralPath $key -ErrorAction Stop
    $delayed=$properties.PSObject.Properties['DelayedAutostart']
    if(($null -ne $delayed) -ne $Snapshot.DelayedPresent -or ($Snapshot.DelayedPresent -and [int]$delayed.Value -ne $Snapshot.DelayedValue)){throw 'Delayed service startup restoration could not be verified.'}
}


# ---- lib/Reports ----
# Shared report privacy and persistent manual handover. No collection at load time.
function Assert-AtlasPlainFile {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Path)
    $file = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if ($file.PSIsContainer -or ($file.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Report/checklist must be a plain file.' }
    Assert-AtlasPlainDirectory $file.DirectoryName
}

function Protect-AtlasReportText {
    [CmdletBinding()]
    param([AllowEmptyString()][string]$Text, [string[]]$SensitiveValues = @())
    $result = $Text
    # Recovery secrets, product keys, user paths, SIDs, emails and network identifiers.
    foreach ($pattern in @(
        '(?i)\b(?:[A-Z0-9]{5}-){4}[A-Z0-9]{5}\b',
        '\b(?:\d{6}-){7}\d{6}\b',
        '(?i)\b[A-Z]:\\Users\\[^\\\s<>"'']+',
        '(?i)\bS-1-5-21-(?:\d+-){2,3}\d+\b',
        '(?i)\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b',
        '(?i)\b(?:[A-F0-9]{2}[:-]){5}[A-F0-9]{2}\b',
        '\b(?:\d{1,3}\.){3}\d{1,3}\b'
    )) { $result = [regex]::Replace($result, $pattern, '[REDACTED]') }
    $result = [regex]::Replace($result, '(?i)(?<![a-z0-9:])(?:[a-f0-9]{0,4}:){2,}[a-f0-9]{0,4}(?:%[\w.-]+)?(?![a-z0-9:])', {
        param($match)
        $address = $null
        if ([Net.IPAddress]::TryParse($match.Value, [ref]$address) -and $address.AddressFamily -eq [Net.Sockets.AddressFamily]::InterNetworkV6) { return '[REDACTED]' }
        return $match.Value
    })
    $values = @($SensitiveValues) + @($env:COMPUTERNAME, $env:USERNAME, $env:USERPROFILE)
    foreach ($value in @($values | Where-Object { $_ -and $_.Length -ge 3 } | Select-Object -Unique | Sort-Object Length -Descending)) {
        foreach ($encoded in @($value, [Net.WebUtility]::HtmlEncode($value))) {
            $result = [regex]::Replace($result, [regex]::Escape($encoded), '[REDACTED]', [Text.RegularExpressions.RegexOptions]::IgnoreCase)
        }
    }
    return $result
}

function Protect-AtlasReportObject {
    [CmdletBinding()]
    param([AllowNull()][object]$InputObject, [string[]]$SensitiveValues = @())
    if ($null -eq $InputObject) { return $null }
    if ($InputObject -is [string]) { return (Protect-AtlasReportText $InputObject -SensitiveValues $SensitiveValues) }
    if ($InputObject -is [ValueType]) { return $InputObject }
    if ($InputObject -is [Collections.IDictionary] -or $InputObject -is [pscustomobject]) {
        $result = [ordered]@{}
        $names = if ($InputObject -is [Collections.IDictionary]) { @($InputObject.Keys) } else { @($InputObject.PSObject.Properties.Name) }
        foreach ($name in $names) {
            if ($name -match '^(?i:Serial(?:Number)?|UUID|ProcessorId|MachineGuid|MacAddress|IpAddress(?:es)?|UserName|ComputerName|Computer|HostName|Owner|Client|Cliente|Customer|Document|SSID|BSSID|RecoveryPassword|ProductKey|KeyProtectorId|FullName|FileSystemLabel|PNPDeviceId|DeviceId|InstanceId|DeviceInstanceId)$') {
                $result[$name] = '[REDACTED]'
            } else { $result[$name] = Protect-AtlasReportObject $InputObject.$name -SensitiveValues $SensitiveValues }
        }
        return [pscustomobject]$result
    }
    if ($InputObject -is [Collections.IEnumerable]) {
        $items = @($InputObject | ForEach-Object { Protect-AtlasReportObject $_ -SensitiveValues $SensitiveValues })
        return ,$items
    }
    return (Protect-AtlasReportText ([string]$InputObject) -SensitiveValues $SensitiveValues)
}

function Write-AtlasShareableReport {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][AllowEmptyString()][string]$Content,
        [Parameter(Mandatory)][string]$Tool, [string[]]$SensitiveValues = @())
    Assert-AtlasPlainDirectory (Split-Path -Parent ([IO.Path]::GetFullPath($Path)))
    if (Test-Path -LiteralPath $Path) { Assert-AtlasPlainFile $Path }
    $trace = Get-AtlasReportTrace -Tool $Tool
    if ([IO.Path]::GetExtension($Path) -eq '.json') {
        $report = $Content | ConvertFrom-Json -ErrorAction Stop
        $report | Add-Member -NotePropertyName Trace -NotePropertyValue $trace -Force
        $report = Protect-AtlasReportObject $report -SensitiveValues $SensitiveValues
        $contentToSave = $report | ConvertTo-Json -Depth 20
    } else {
        $traceText = $trace | ConvertTo-Json -Compress
        $suffix = if ([IO.Path]::GetExtension($Path) -eq '.html') { "`n<!-- " + [Net.WebUtility]::HtmlEncode($traceText) + " -->" } else { "`n`n$traceText" }
        $contentToSave = Protect-AtlasReportText -Text ($Content + $suffix) -SensitiveValues $SensitiveValues
    }
    [IO.File]::WriteAllText($Path, $contentToSave, [Text.UTF8Encoding]::new($false))
}

function Get-AtlasReportTrace {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Tool)
    $version = Get-Variable AtlasVersion -Scope Script -ValueOnly -ErrorAction SilentlyContinue
    $commit = Get-Variable AtlasReleaseCommit -Scope Script -ValueOnly -ErrorAction SilentlyContinue
    return [pscustomobject][ordered]@{
        SchemaVersion = 1; Tool = $Tool
        Version = if ($version) { [string]$version } else { 'development' }
        Commit = if ($commit) { [string]$commit } else { 'unpublished' }
        GeneratedUtc = [datetime]::UtcNow.ToString('o')
        Privacy = 'Redacted by default; review free text before sharing.'
        Coverage = 'Observations and manual confirmations; not a health, activation or recovery-escrow certificate.'
    }
}

function Get-AtlasHandoverChecklist {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][string[]]$Items)
    if (-not $Items.Count) { throw 'Checklist items are required.' }
    if (Test-Path -LiteralPath $Path) {
        Assert-AtlasPlainFile $Path
        $state = Get-Content -LiteralPath $Path -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        if ($state.SchemaVersion -ne 1 -or $state.HandoverId -cnotmatch '^[a-f0-9]{32}$' -or -not $state.Trace -or @($state.Items).Count -ne $Items.Count) { throw 'Unsupported checklist schema or changed item count; start a new handover.' }
        for ($index = 0; $index -lt $Items.Count; $index++) {
            $row = $state.Items[$index]
            if ($row.Id -ne ($index + 1) -or $row.Text -cne $Items[$index] -or
                $row.State -notin @('NotVerified','ManualConfirmed','NotApplicable') -or
                ($row.State -ne 'NotVerified' -and (-not $row.CheckedUtc -or -not $row.Evidence))) { throw 'Invalid checklist entry. Existing evidence was not changed.' }
        }
        return $state
    }
    $index = 0
    return [pscustomobject][ordered]@{
        SchemaVersion = 1; HandoverId = [guid]::NewGuid().ToString('N')
        Trace = Get-AtlasReportTrace -Tool 'PC Handover'
        Items = @($Items | ForEach-Object { $index++; [pscustomobject]@{ Id=$index; Text=$_; State='NotVerified'; CheckedUtc=$null; Evidence=$null } })
    }
}

function Save-AtlasHandoverChecklist {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][object]$Checklist)
    $directory = Split-Path -Parent ([IO.Path]::GetFullPath($Path))
    Assert-AtlasPlainDirectory $directory
    if (Test-Path -LiteralPath $Path) { Assert-AtlasPlainFile $Path }
    $temporary = Join-Path $directory ('checklist-' + [guid]::NewGuid().ToString('N') + '.tmp')
    try {
        $json = $Checklist | ConvertTo-Json -Depth 8
        [IO.File]::WriteAllText($temporary, $json, [Text.UTF8Encoding]::new($false))
        Get-AtlasHandoverChecklist -Path $temporary -Items @($Checklist.Items | ForEach-Object Text) | Out-Null
        if ([IO.File]::Exists($Path)) { [IO.File]::Replace($temporary, $Path, ($Path + '.previous'), $true) }
        else { [IO.File]::Move($temporary, $Path) }
    } finally { if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary -Force } }
}


# ============================================================
# Atlas PC Support - Tool runner
# Ejecuta una herramienta en una nueva ventana de PowerShell.
#
# Distribution uses only the verified release directory. No mutable cache or
# hot hash refresh. Explicit development mode permits a source checkout.
# Child wrappers include the declared runtime context and all shared libraries.

if (-not $script:AtlasToolHashes) { $script:AtlasToolHashes = @{} }

function Get-AtlasSecureRunDir {
    [CmdletBinding()]
    param()

    if ($script:AtlasSecureRunDir -and (Test-Path -LiteralPath $script:AtlasSecureRunDir)) {
        return $script:AtlasSecureRunDir
    }

    $dir = Initialize-AtlasSecureDirectory -Path '%LOCALAPPDATA%\AtlasPC\secure-run'
    if (-not $dir) {
        $dir = Expand-AtlasPath '%LOCALAPPDATA%\AtlasPC\secure-run'
        if (-not (Test-Path -LiteralPath $dir)) {
            New-Item -ItemType Directory -Path $dir -Force | Out-Null
        }
    }
    $script:AtlasSecureRunDir = $dir
    return $script:AtlasSecureRunDir
}

function Get-AtlasSHA256 {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Path)
    try {
        # Tool scripts are text. Hash in canonical UTF-8 + LF form so checks are
        # stable across CRLF/LF differences between local checkout and GitHub raw.
        $text = Get-Content -Raw -LiteralPath $Path -Encoding UTF8 -ErrorAction Stop
        $normalized = ($text -replace "`r`n", "`n") -replace "`r", "`n"
        $bytes = [System.Text.UTF8Encoding]::new($false).GetBytes($normalized)
        $sha = [System.Security.Cryptography.SHA256]::Create()
        try {
            $hashBytes = $sha.ComputeHash($bytes)
            return ([System.BitConverter]::ToString($hashBytes) -replace '-', '').ToLowerInvariant()
        } finally {
            $sha.Dispose()
        }
    } catch {
        Write-AtlasLog "No se pudo calcular SHA256 de '$Path': $_" -Level WARN -Tool 'Runner'
        return $null
    }
}

function Get-AtlasToolExpectedHash {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$FileName)

    if (-not $script:AtlasToolHashes) { return $null }
    if ($script:AtlasToolHashes -is [hashtable]) {
        if ($script:AtlasToolHashes.ContainsKey($FileName)) {
            return [string]$script:AtlasToolHashes[$FileName]
        }
        return $null
    }

    try {
        $prop = $script:AtlasToolHashes.PSObject.Properties[$FileName]
        if ($prop) { return [string]$prop.Value }
    } catch {}

    return $null
}

function Test-AtlasToolFileIntegrity {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$FileName,
        [string]$SourceLabel = 'unknown'
    )

    if (-not (Test-Path -LiteralPath $Path)) { return $false }

    try {
        $fi = Get-Item -LiteralPath $Path -ErrorAction Stop
        if ($fi.Length -lt 128) {
            Write-AtlasLog "Archivo tool demasiado corto (sospechoso): $Path" -Level ERROR -Tool 'Runner'
            return $false
        }
    } catch {
        Write-AtlasLog "No se pudo inspeccionar archivo tool '$Path': $_" -Level ERROR -Tool 'Runner'
        return $false
    }

    $expected = Get-AtlasToolExpectedHash -FileName $FileName
    if (-not $expected) {
        if ($SourceLabel -eq 'local-src') {
            Write-AtlasLog "Sin hash esperado para '$FileName' en local-src; permitido solo para desarrollo." -Level WARN -Tool 'Runner'
            return $true
        }
        Write-AtlasLog "Sin hash esperado para '$FileName' (origen=$SourceLabel). Bloqueado por politica fail-closed." -Level ERROR -Tool 'Runner'
        return $false
    }

    $actual = Get-AtlasSHA256 -Path $Path
    if (-not $actual) { return $false }
    if ($actual -ne $expected.ToLowerInvariant()) {
        Write-AtlasLog "Hash invalido para '$FileName' (origen=$SourceLabel). Esperado=$expected Actual=$actual" -Level ERROR -Tool 'Runner'
        return $false
    }

    return $true
}

function Invoke-AtlasRunnerTempCleanup {
    [CmdletBinding()]
    param(
        [string]$TempDir,
        [int]$MaxAgeHours = 24
    )

    if (-not $TempDir) { $TempDir = Get-AtlasSecureRunDir }
    if (-not (Test-Path -LiteralPath $TempDir)) { return }

    $cutoff = (Get-Date).AddHours(-1 * [math]::Abs($MaxAgeHours))
    try {
        Get-ChildItem -LiteralPath $TempDir -File -ErrorAction SilentlyContinue |
            Where-Object {
                ($_.Name -like 'run-*.ps1' -or $_.Name -like 'run-*.cmd' -or $_.Name -like 'atlas-tool-hashes-*.json') -and
                $_.LastWriteTime -lt $cutoff
            } |
            ForEach-Object {
                Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue
            }
    } catch {
        Write-AtlasLog "Limpieza de temporales fallo: $_" -Level WARN -Tool 'Runner'
    }
}

function Get-AtlasToolScript {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$FunctionName)
    if ($FunctionName -cnotmatch '^Invoke-[A-Za-z0-9-]+$') { throw 'Invalid tool function name.' }
    if (-not $script:AtlasRoot) { throw 'Atlas release directory is not configured.' }
    $fileName = "$FunctionName.ps1"
    $path = Join-Path $script:AtlasRoot "src/tools/$fileName"
    $label = if ($script:AtlasDevelopmentMode) { 'local-src' } else { 'release' }
    if (-not $script:AtlasDevelopmentMode -and (-not $script:AtlasReleaseCommit -or -not $script:AtlasManifestSha256)) {
        throw 'An approved release context is required. Reopen Atlas from the published link.'
    }
    if (Test-AtlasToolFileIntegrity -Path $path -FileName $fileName -SourceLabel $label) { return $path }
    throw "Tool $fileName is absent or corrupt in this release. Restore the previous release or reinstall the complete bundle."
}

function Get-AtlasToolRuntime {
    [CmdletBinding()]
    param([Parameter(Mandatory)][hashtable]$Tool)
    if (-not $Tool.runtime -or $Tool.runtime.architecture -ne 'x64' -or -not $Tool.runtime.minimumVersion -or @($Tool.runtime.libraries).Count -eq 0) { throw 'A supported x64 runtime contract is required.' }
    foreach ($library in @($Tool.runtime.libraries)) {
        if ($library -notin @('ToolKit','Dependencies','PS7','Release','Reports','Operations')) { throw "Unknown child library: $library" }
    }
    if ($Tool.runtime.engine -eq 'windows-powershell') {
        if ([version]$Tool.runtime.minimumVersion -gt [version]'5.1') { throw 'This contract requires a newer Windows PowerShell.' }
        $relative = if ([Environment]::Is64BitOperatingSystem -and -not [Environment]::Is64BitProcess) { 'Sysnative' } else { 'System32' }
        $path = Join-Path $env:SystemRoot "$relative/WindowsPowerShell/v1.0/powershell.exe"
        if (-not [Environment]::Is64BitOperatingSystem -or -not (Test-Path -LiteralPath $path)) { throw 'Windows PowerShell 5.1 x64 is unavailable.' }
        return $path
    }
    if ($Tool.runtime.engine -eq 'pwsh') {
        $path = $script:AtlasPS7CachedPath
        if (-not $path -or -not (Test-Path -LiteralPath $path)) { throw 'The declared PowerShell 7 runtime is unavailable.' }
        $info = [Diagnostics.FileVersionInfo]::GetVersionInfo($path)
        if ($info.ProductVersion -notmatch '^(\d+\.\d+\.\d+)' -or [version]$Matches[1] -lt [version]$Tool.runtime.minimumVersion) { throw 'The detected PowerShell 7 version does not satisfy this tool.' }
        $stream = [IO.File]::OpenRead($path)
        $reader = [IO.BinaryReader]::new($stream)
        try {
            $stream.Position = 0x3c
            $stream.Position = $reader.ReadInt32() + 4
            if ($reader.ReadUInt16() -ne 0x8664) { throw 'The declared runtime requires an x64 executable.' }
        } finally { $reader.Dispose() }
        return $path
    }
    throw 'Unknown runtime engine; no silent fallback is permitted.'
}

function Invoke-AtlasTool {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] [hashtable]$Tool,
        [hashtable]$Branding
    )

    Invoke-AtlasRunnerTempCleanup
    $availability = Test-AtlasToolAvailability -Tool $Tool
    if (-not $availability.Available) { throw $availability.Reason }
    Write-AtlasLog "Ejecutando: $($Tool.name) [$($Tool.id)]" -Tool 'Runner'

    $function = $Tool.function

    $runInNew = $true
    if ($Tool.ContainsKey('runsInNewWindow')) {
        $runInNew = [bool]$Tool.runsInNewWindow
    }

    if (-not $runInNew) {
        # Inline (sin nueva ventana): cargar el script en el scope actual y llamar la funcion.
        $toolPath = Get-AtlasToolScript -FunctionName $function
        if (-not $toolPath) {
            $msg = "No se pudo obtener la tool '$function'."
            [System.Windows.MessageBox]::Show($msg, 'Atlas PC Support', 'OK', 'Error') | Out-Null
            return
        }
        try {
            . $toolPath
            & $function
        } catch {
            Write-AtlasLog "Error en ${function}: $_" -Level ERROR -Tool 'Runner'
            [System.Windows.MessageBox]::Show("Error: $_", 'Atlas PC Support', 'OK', 'Error') | Out-Null
        }
        return
    }

    # ----------- Obtener ruta del script de la tool -----------
    $toolScriptPath = Get-AtlasToolScript -FunctionName $function
    if (-not $toolScriptPath) {
        $msg = "No se pudo obtener la tool '$($Tool.name)'. Verifica conexion o integridad."
        Write-AtlasLog $msg -Level ERROR -Tool 'Runner'
        [System.Windows.MessageBox]::Show($msg, 'Atlas PC Support', 'OK', 'Error') | Out-Null
        return
    }

    $toolSource = [IO.File]::ReadAllText($toolScriptPath, [Text.Encoding]::UTF8)
    $expected = Get-AtlasToolExpectedHash -FileName "$function.ps1"
    if (-not $script:AtlasDevelopmentMode -and (Get-AtlasTextHash $toolSource) -cne $expected) { throw 'Tool changed before wrapper creation.' }
    $psExe = Get-AtlasToolRuntime -Tool $Tool
    if (-not $script:AtlasChildLibrarySource) { throw 'Required child libraries are unavailable. Reopen the complete Atlas release.' }

    $brandName = if ($Branding -and $Branding.brand -and $Branding.brand.shortName) { $Branding.brand.shortName } else { 'Atlas PC Support' }
    $title = "$brandName - $($Tool.name)"

    # ----------- Script temporal que llama a la tool -----------
    $sb = [System.Text.StringBuilder]::new()
    [void]$sb.AppendLine('# Atlas PC Support - runner temp script')
    [void]$sb.AppendLine('$ErrorActionPreference = ''Stop''')
    [void]$sb.AppendLine('try { $Host.UI.RawUI.WindowTitle = ' + ("'{0}'" -f ($title -replace "'","''")) + ' } catch {}')
    [void]$sb.AppendLine('')
    # All child libraries come from the already verified launcher, without downloads.
    # Missing helpers must stop the tool, not downgrade the validation policy.
    # The shared source begins with the native runtime header, before JSON autoload.
    [void]$sb.AppendLine($script:AtlasChildLibrarySource)
    $context = @{
        AtlasVersion = $script:AtlasVersion
        AtlasRoot = $script:AtlasRoot
        AtlasReleaseCommit = $script:AtlasReleaseCommit
        AtlasManifestSha256 = $script:AtlasManifestSha256
        AtlasDevelopmentMode = [bool]$script:AtlasDevelopmentMode
        AtlasOfflineRoot = $env:ATLAS_OFFLINE_ROOT
    } | ConvertTo-Json -Compress
    [void]$sb.AppendLine("`$atlasContext = '" + $context.Replace("'", "''") + "' | ConvertFrom-Json")
    [void]$sb.AppendLine('foreach ($entry in $atlasContext.PSObject.Properties) { Set-Variable -Name $entry.Name -Value $entry.Value -Scope Script }')
    [void]$sb.AppendLine('$env:ATLAS_OFFLINE_ROOT = $script:AtlasOfflineRoot')
    $toolContract = $Tool | ConvertTo-Json -Depth 12 -Compress
    [void]$sb.AppendLine("`$atlasToolContract = ConvertFrom-AtlasJson '" + $toolContract.Replace("'", "''") + "'")
    [void]$sb.AppendLine('$availability = Test-AtlasToolAvailability -Tool $atlasToolContract -Capabilities (Get-AtlasPlatformCapabilities -Refresh)')
    [void]$sb.AppendLine('if (-not $availability.Available) { throw $availability.Reason }')
    [void]$sb.AppendLine($toolSource)
    [void]$sb.AppendLine('')
    [void]$sb.AppendLine('$atlasToolExitCode = 0')
    [void]$sb.AppendLine('try {')
    [void]$sb.AppendLine("    $function")
    [void]$sb.AppendLine('} catch {')
    [void]$sb.AppendLine('    $atlasToolExitCode = 1')
    [void]$sb.AppendLine('    Write-Host ""')
    [void]$sb.AppendLine("    Write-Host ('[!] Error en $function : ' + `$_.Exception.Message) -ForegroundColor Red")
    [void]$sb.AppendLine('    Write-Host ""')
    [void]$sb.AppendLine('    Write-Host "Traza:" -ForegroundColor DarkGray')
    [void]$sb.AppendLine('    Write-Host $_.ScriptStackTrace -ForegroundColor DarkGray')
    [void]$sb.AppendLine('} finally {')
    [void]$sb.AppendLine('    Write-Host ""')
    [void]$sb.AppendLine('    Write-Host "============================================"')
    [void]$sb.AppendLine('    Write-Host "  Tool finalizada. Presiona ENTER para cerrar."')
    [void]$sb.AppendLine('    Write-Host "============================================"')
    [void]$sb.AppendLine('    [void](Read-Host)')
    [void]$sb.AppendLine('    try { Remove-Item -LiteralPath $PSCommandPath -Force -ErrorAction SilentlyContinue } catch {}')
    [void]$sb.AppendLine('}')
    [void]$sb.AppendLine('exit $atlasToolExitCode')

    $tempDir = Get-AtlasSecureRunDir
    if (-not (Test-Path -LiteralPath $tempDir)) {
        New-Item -ItemType Directory -Path $tempDir -Force | Out-Null
    }
    $stamp       = "$($Tool.id)-$(Get-Random)"
    $tempScript  = Join-Path $tempDir "run-$stamp.ps1"

    $utf8WithBom = [System.Text.UTF8Encoding]::new($true)
    [System.IO.File]::WriteAllText($tempScript, $sb.ToString(), $utf8WithBom)

    # Validate wrapper parse before launch to avoid "nothing happens" failures.
    try {
        $parseErrors = $null
        $parseTokens = $null
        [System.Management.Automation.Language.Parser]::ParseFile($tempScript, [ref]$parseTokens, [ref]$parseErrors) | Out-Null
        if ($parseErrors -and $parseErrors.Count -gt 0) {
            $first = $parseErrors[0]
            $line = if ($first.Extent -and $first.Extent.StartLineNumber) { $first.Extent.StartLineNumber } else { '?' }
            $msg = "Wrapper invalido para '$($Tool.name)' (linea $line): $($first.Message)"
            Write-AtlasLog $msg -Level ERROR -Tool 'Runner'
            [System.Windows.MessageBox]::Show($msg, 'Atlas PC Support', 'OK', 'Error') | Out-Null
            return
        }
    } catch {
        Write-AtlasLog "No se pudo validar parser del wrapper temporal: $_" -Level WARN -Tool 'Runner'
    }

    $psArgs = @(
        '-NoLogo',
        '-NoProfile',
        '-Sta',
        '-ExecutionPolicy', 'RemoteSigned',
        '-File', ('"{0}"' -f $tempScript)
    )

    $startArgs = @{
        FilePath         = $psExe
        ArgumentList     = $psArgs
        WorkingDirectory = (Split-Path -Parent $toolScriptPath)
    }
    if ($Tool.requiresAdmin -and -not (Test-IsAdmin)) {
        $startArgs.Verb = 'RunAs'
    }

    try {
        Start-Process @startArgs | Out-Null
    } catch {
        $errMsg = "No se pudo lanzar la tool '$($Tool.name)': $($_.Exception.Message)"
        Write-AtlasLog $errMsg -Level ERROR -Tool 'Runner'
        [System.Windows.MessageBox]::Show($errMsg, 'Atlas PC Support', 'OK', 'Error') | Out-Null
        Remove-Item -LiteralPath $tempScript -Force -ErrorAction SilentlyContinue
    }
}


# ============================================================
# Atlas PC Support — MainWindow.ps1
# Construye la ventana WPF, aplica branding, renderiza herramientas.
# ============================================================

function ConvertTo-AtlasHex {
    param([string]$Hex)
    if (-not $Hex) { return "#FFFFFF" }

    $clean = ([string]$Hex).Trim()
    if ($clean.StartsWith('#')) { $clean = $clean.Substring(1) }
    if ($clean -match '^[0-9A-Fa-f]{3}$') {
        $clean = ($clean.ToCharArray() | ForEach-Object { "$_$_" }) -join ''
    }
    if ($clean -notmatch '^[0-9A-Fa-f]{6}$') {
        return "#FFFFFF"
    }

    return ('#{0}' -f $clean.ToUpperInvariant())
}

function ConvertTo-AtlasXamlSafe {
    param($Value)
    if ($null -eq $Value) { return '' }
    return [System.Security.SecurityElement]::Escape([string]$Value)
}

function ConvertTo-AtlasIntOrDefault {
    param($Value, [int]$Default = 0)
    try { return [int]$Value } catch { return $Default }
}

# Recorre el arbol logico de WPF buscando el primer descendiente del tipo indicado.
function Find-AtlasDescendant {
    param(
        [Parameter(Mandatory)] $Root,
        [Parameter(Mandatory)] [type]$Type
    )
    if ($null -eq $Root) { return $null }
    if ($Root -is $Type) { return $Root }

    # Intentar varios "hijos" segun el tipo de contenedor WPF
    $kids = @()
    if ($Root.PSObject.Properties.Match('Child').Count -gt 0 -and $Root.Child) {
        $kids += $Root.Child
    }
    if ($Root.PSObject.Properties.Match('Children').Count -gt 0 -and $Root.Children) {
        foreach ($c in $Root.Children) { $kids += $c }
    }
    if ($Root.PSObject.Properties.Match('Content').Count -gt 0 -and $Root.Content -and ($Root.Content -is [System.Windows.DependencyObject])) {
        $kids += $Root.Content
    }
    if ($Root.PSObject.Properties.Match('Items').Count -gt 0 -and $Root.Items) {
        foreach ($c in $Root.Items) {
            if ($c -is [System.Windows.DependencyObject]) { $kids += $c }
        }
    }

    foreach ($kid in $kids) {
        $found = Find-AtlasDescendant -Root $kid -Type $Type
        if ($found) { return $found }
    }
    return $null
}

function Get-AtlasPalette {
    param([hashtable]$Branding)

    $accent = ConvertTo-AtlasHex $Branding.theme.accentColor
    $dark   = [bool]$Branding.theme.darkMode
    $secondary = if ($Branding.theme.secondaryColor) { ConvertTo-AtlasHex $Branding.theme.secondaryColor } else { $null }

    if ($dark) {
        # Si hay secondaryColor (ej. Atlas navy #002147), tínta sutilmente el fondo
        $bg      = if ($secondary) { (Get-AtlasColorShift $secondary -15) } else { '#0F1115' }
        $surface = if ($secondary) { (Get-AtlasColorShift $secondary 0)   } else { '#1A1D23' }
        $surfAlt = if ($secondary) { (Get-AtlasColorShift $secondary 15)  } else { '#23272F' }
        return @{
            BgColor          = $bg
            SurfaceColor     = $surface
            SurfaceAltColor  = $surfAlt
            BorderColor      = '#2E333D'
            TextPrimary      = '#F5F5F5'
            TextSecondary    = '#C5C7CC'
            TextMuted        = '#9BA0AA'
            AccentColor      = $accent
            AccentHover      = (Get-AtlasColorShift $accent 20)
            AccentPressed    = (Get-AtlasColorShift $accent -20)
        }
    } else {
        return @{
            BgColor          = '#F7F8FA'
            SurfaceColor     = '#FFFFFF'
            SurfaceAltColor  = '#F0F1F4'
            BorderColor      = '#E0E2E7'
            TextPrimary      = '#1A1D23'
            TextSecondary    = '#434750'
            TextMuted        = '#8A8E95'
            AccentColor      = $accent
            AccentHover      = (Get-AtlasColorShift $accent -10)
            AccentPressed    = (Get-AtlasColorShift $accent -25)
        }
    }
}

function Get-AtlasColorShift {
    param([string]$Hex, [int]$Delta)
    $safeHex = ConvertTo-AtlasHex $Hex
    $h = $safeHex.TrimStart('#')
    $r = [Convert]::ToInt32($h.Substring(0,2), 16)
    $g = [Convert]::ToInt32($h.Substring(2,2), 16)
    $b = [Convert]::ToInt32($h.Substring(4,2), 16)
    $r = [Math]::Max(0, [Math]::Min(255, $r + $Delta))
    $g = [Math]::Max(0, [Math]::Min(255, $g + $Delta))
    $b = [Math]::Max(0, [Math]::Min(255, $b + $Delta))
    return ('#{0:X2}{1:X2}{2:X2}' -f $r, $g, $b)
}

